// HML: convite administrativo e ciclo autenticado de confirmações.
import { criarHandler } from './handler.ts'
Deno.serve(criarHandler(Deno.env))

import {prevalidarMetaHml} from './prevalidarMetaHml.ts'
import {orquestrarConviteHml} from './orquestradorConviteHml.ts'
import {NOME_TEMPLATE_HML} from './solicitacaoTemplateMeta.ts'
import {criarTransporteMetaHml,envioMetaHmlHabilitado as envioMetaPermitido} from '../mensageria-outbox-hml/transporteMetaHml.ts'
import {criarAdaptadorRpcOutboxHml} from '../mensageria-outbox-hml/adaptadorRpcOutboxHml.ts'
import {executarUmAgradecimentoHml} from '../mensageria-outbox-hml/orquestradorDespachoHml.ts'

export const REF = 'jgtctzqieyorhvqxjbpk'
const BASE = 'https://' + REF + '.supabase.co'
const ORIGENS = new Set(['http://127.0.0.1:5173','http://localhost:5173'])
type Env = { get(nome:string):string|undefined }
type Fetch = typeof fetch
type Config = {key:string; adminId:string}
const uuid = /^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/i

function resposta(status:number,data:Record<string,unknown>,origin:string|null) {
  return Response.json(data,{status,headers:{
    'access-control-allow-origin': origin && ORIGENS.has(origin) ? origin : 'null',
    'access-control-allow-headers':'authorization,apikey,content-type,x-client-info',
    'access-control-allow-methods':'POST,OPTIONS',
    'cache-control':'no-store','vary':'Origin'
  }})
}
function config(env:Env):Config|null {
  if (env.get('SUPABASE_URL')!==BASE || env.get('HML_PROJECT_REF')!==REF) return null
  const key=env.get('SUPABASE_SERVICE_ROLE_KEY')??''
  const adminId=env.get('HML_OPERATOR_UUID')??''
  if (!key || !uuid.test(adminId)) return null
  return {key,adminId}
}

async function backend(c:Config,endpoint:string,credencial:string,method:'GET'|'POST',
  fetchImpl:Fetch, body?:Record<string,unknown>) {
  const res=await fetchImpl(BASE+endpoint,{
    method,redirect:'error',signal:AbortSignal.timeout(12000),
    headers:{apikey:c.key,authorization:'Bearer '+credencial,'content-type':'application/json'},
    ...(method==='POST'?{body:JSON.stringify(body)}:{})
  })
  return {ok:res.ok,data:await res.json().catch(()=>null)}
}
async function operadorAutorizado(req:Request,c:Config,fetchImpl:Fetch) {
  const auth=req.headers.get('authorization')??''
  if (!/^Bearer [A-Za-z0-9_.-]{20,8192}$/.test(auth)) return false
  const jwt=auth.slice(7)
  const user=await backend(c,'/auth/v1/user',jwt,'GET',fetchImpl)
  if (!user.ok || user.data?.id!==c.adminId ||
      user.data?.app_metadata?.role!=='internal' ||
      user.data?.app_metadata?.whatsapp_admin!==true) return false
  const valid=await backend(c,'/rest/v1/rpc/mensageria_hml_autorizar_operador',
    jwt,'POST',fetchImpl,{p_expected:c.adminId})
  return valid.ok && valid.data===true
}

export function criarHandler(env:Env,fetchImpl:Fetch=fetch) {
  return async function(req:Request):Promise<Response> {
    const origem=req.headers.get('origin')
    if(origem && !ORIGENS.has(origem))return resposta(403,{codigo:'ORIGEM_NEGADA'},origem)
    if(req.method==='OPTIONS')return new Response(null,{status:204,headers:{
      'access-control-allow-origin':origem && ORIGENS.has(origem)?origem:'null',
      'access-control-allow-headers':'authorization,apikey,content-type,x-client-info',
      'access-control-allow-methods':'POST,OPTIONS','vary':'Origin'
    }})
    if(req.method!=='POST' || !new URL(req.url).pathname.endsWith('/mensageria-confirmacao-hml'))
      return resposta(405,{codigo:'METODO_NEGADO'},origem)
    if(Number(req.headers.get('content-length')??0)>4096)
      return resposta(413,{codigo:'CORPO_GRANDE'},origem)
    const c=config(env)
    if(!c)return resposta(503,{codigo:'HML_NAO_CONFIGURADA'},origem)
    let autorizado=false
    try{autorizado=await operadorAutorizado(req,c,fetchImpl)}catch{/* não expor credenciais */}
    if(!autorizado)return resposta(403,{codigo:'OPERADOR_NAO_AUTORIZADO'},origem)
    let body:Record<string,unknown>
    try {
      const text=await req.text()
      if(text.length>4096)throw Error('grande')
      const json:unknown=JSON.parse(text)
      if(!json||typeof json!=='object'||Array.isArray(json))throw Error('invalido')
      body=json as Record<string,unknown>
    } catch{return resposta(400,{codigo:'CORPO_INVALIDO'},origem)}

    if(body.acao==='prevalidar_meta'){
      if(Object.keys(body).length!==1)return resposta(400,{codigo:'CORPO_INVALIDO'},origem)
      return resposta(200,await prevalidarMetaHml(env,fetchImpl),origem)
    }

    // O ciclo usa a mesma autenticação administrativa das demais ações.
    const ciclo=body.acao==='processar_ciclo'

    const destinoPermitido=env.get('HML_TEST_RECIPIENT_E164')??''
    const rpc=async (nome:string,params:Record<string,unknown>)=>{
      const r=await backend(c,'/rest/v1/rpc/mensageria_hml_'+nome,c.key,'POST',fetchImpl,{
        ...params,p_operador:c.adminId
      })
      if(!r.ok||!r.data||typeof r.data!=='object'||Array.isArray(r.data))throw Error('RPC_INDISPONIVEL')
      return r.data
    }
    async function operacao(acao='status',segundos:number|null=null){
      return rpc('operacao',{p_acao:acao,p_segundos:segundos})
    }
    if(body.acao==='operacao'){
      const comando=body.comando
      if(typeof comando!=='string'||!['status','ligar_receptor','desligar_receptor','ligar_processamento',
        'desligar_processamento','abrir_envio','fechar_envio','emergencia'].includes(comando)||
        Object.keys(body).some(chave=>!['acao','comando','segundos'].includes(chave))||
        (comando==='abrir_envio'? !Number.isInteger(body.segundos)||Number(body.segundos)<1||Number(body.segundos)>180
          :body.segundos!==undefined))
        return resposta(400,{codigo:'COMANDO_INVALIDO'},origem)
      if(comando==='abrir_envio'){
        if(env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')
          return resposta(503,{codigo:'ENVIO_DESATIVADO'},origem)
        const meta=await prevalidarMetaHml(env,fetchImpl)
        if(!meta.credencial_aceita||!meta.telefone_acessivel||!meta.telefone_na_waba||
          meta.aplicativo_hml!==true||meta.permissao_envio!==true)
          return resposta(409,{codigo:'META_NAO_VALIDADA'},origem)
      }
      try{
        const r=await operacao(comando,comando==='abrir_envio'?Number(body.segundos):null)
        if(r.status!=='ok')return resposta(409,{codigo:r.status==='janela_ja_ativa'?'JANELA_JA_ATIVA':'OPERACAO_RECUSADA'},origem)
        return resposta(200,{receptor:r.receptor===true&&env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')!=='true',
          processamento:r.processamento===true,
          envio_expira_em:env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true'?null:r.envio_expira_em,
          revisao:r.revisao,atualizado_em:r.atualizado_em},origem)
      }catch{return resposta(503,{codigo:'CONTROLES_INDISPONIVEIS'},origem)}
    }
    if(body.acao==='evidencia_operacao'){
      if(Object.keys(body).length!==1)return resposta(400,{codigo:'CORPO_INVALIDO'},origem)
      try{
        const dados=await rpc('evidencia_operacao',{})
        return resposta(dados.status==='ok'?200:503,dados,origem)
      }catch{return resposta(503,{codigo:'EVIDENCIA_INDISPONIVEL'},origem)}
    }

    if(body.acao==='config_lembrete'||body.acao==='simular_lembretes'){
      try{
        if(body.acao==='simular_lembretes'){
          if(Object.keys(body).length!==1)return resposta(400,{codigo:'CORPO_INVALIDO'},origem)
          const r=await rpc('simular_lembretes',{})
          return resposta(r.status==='ok'?200:409,r,origem)
        }
        if(body.comando==='status'&&Object.keys(body).length===2){
          const r=await rpc('configurar_lembrete',{p_acao:'status'})
          return resposta(r.status==='ok'?200:409,r,origem)
        }
        const allowed=['acao','comando','revisao','antecedencia','vespera','mesmoDia']
        if(body.comando!=='salvar'||Object.keys(body).length!==allowed.length||
           Object.keys(body).some(k=>!allowed.includes(k))||
           typeof body.revisao!=='number'||!Number.isSafeInteger(body.revisao)||body.revisao<1||
           typeof body.antecedencia!=='number'||!Number.isInteger(body.antecedencia)||body.antecedencia<24||body.antecedencia>720||
           typeof body.vespera!=='string'||!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(body.vespera)||
           typeof body.mesmoDia!=='number'||!Number.isInteger(body.mesmoDia)||body.mesmoDia<1||body.mesmoDia>23)
          return resposta(400,{codigo:'CONFIG_INVALIDA'},origem)
        // Fase de simulação: nunca habilitar envio pela edição de horários.
        const r=await rpc('configurar_lembrete',{p_acao:'salvar',p_revisao:body.revisao,p_ativo:false,
          p_antecedencia:body.antecedencia,p_vespera:body.vespera,p_mesmo_dia:body.mesmoDia})
        return resposta(r.status==='ok'?200:409,r,origem)
      }catch{return resposta(503,{codigo:'CONFIG_LEMBRETE_INDISPONIVEL'},origem)}
    }
    if(body.acao==='listar_atendimentos'){
      try{
        const r=await rpc('contexto_convite',{p_atendimento:null,p_preparo:null})
        if(r.status!=='ok'||!Array.isArray(r.itens))throw Error('AGENDA_INDISPONIVEL')
        return resposta(200,{itens:r.itens},origem)
      }catch{return resposta(503,{codigo:'AGENDA_INDISPONIVEL'},origem)}
    }
    let controles:Record<string,unknown>|null=null
    if(['enviar_convite','processar_lote','processar_ciclo','processar_item','despachar_agradecimento'].includes(String(body.acao))){
      try{controles=await operacao()}catch{return resposta(503,{codigo:'CONTROLES_INDISPONIVEIS'},origem)}
      if(controles.status!=='ok')return resposta(503,{codigo:'CONTROLES_INDISPONIVEIS'},origem)
    }
    const expira=typeof controles?.envio_expira_em==='string'?controles.envio_expira_em:null
    const ambiente={get(nome:string){
      if(nome==='HML_OUTBOX_SEND_EXPIRES_AT')return expira??undefined
      if(['HML_CONFIRMATION_REAL_SEND_ENABLED','HML_OUTBOX_SEND_ENABLED','HML_OUTBOX_RPC_ENABLED'].includes(nome))
        return expira&&env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')!=='true'?'true':'false'
      return env.get(nome)
    }}
    const enviar=criarTransporteMetaHml({ambiente,requisitar:async (url,init)=>{
      const atual=await operacao()
      if(atual.status!=='ok'||atual.revisao!==controles?.revisao||atual.envio_expira_em!==expira||
        !expira||Date.parse(expira)<=Date.now()||env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')
        throw Error('AUTORIZACAO_ENCERRADA')
      return fetchImpl(url,init)
    }})
    async function despachar(){
      if(!envioMetaPermitido(ambiente))return null
      const ops=criarAdaptadorRpcOutboxHml({ambiente,requisitar:fetchImpl,enviar})
      return ops.configurado()?executarUmAgradecimentoHml({
        projeto:REF,operadorId:c!.adminId,permitidoE164:destinoPermitido,envioHabilitado:true,
        autorizacaoExpiraIso:expira,agora:()=>new Date(),chaveAleatoria:()=>crypto.randomUUID()
      },ops):null
    }
    if(body.acao==='despachar_agradecimento'){
      if(Object.keys(body).length!==1)return resposta(400,{codigo:'CORPO_INVALIDO'},origem)
      try{
        const r=await despachar()
        return r?resposta(200,{despacho:r},origem):resposta(503,{codigo:'ENVIO_DESATIVADO'},origem)
      }catch{return resposta(503,{codigo:'DESPACHO_INDISPONIVEL'},origem)}
    }
    if(body.acao==='enviar_convite'){
      const envio=envioMetaPermitido(ambiente)
      if(!envio||env.get('HML_CONFIRMATION_APPROVED_TEMPLATE')!==NOME_TEMPLATE_HML)
        return resposta(503,{codigo:'ENVIO_OU_TEMPLATE_NAO_AUTORIZADO'},origem)
      if(typeof body.atendimentoId!=='string'||!uuid.test(body.atendimentoId)||
          Object.keys(body).length!==2)
        return resposta(400,{codigo:'ATENDIMENTO_INVALIDO'},origem)
      const atendimentoId=body.atendimentoId
      try{
        const contexto=async (preparo:string|null)=>rpc('contexto_convite',{
          p_atendimento:atendimentoId,p_preparo:preparo
        })
        const dados=await contexto(null)
        if(dados.status!=='ok'||typeof dados.destino!=='string'||
            !Array.isArray(dados.parametros)||dados.parametros.length!==4||
            !dados.parametros.every((p:unknown)=>typeof p==='string'))
          return resposta(409,{codigo:'ATENDIMENTO_NAO_ELEGIVEL'},origem)
        const resultado=await orquestrarConviteHml({
          projectRef:REF,envioHabilitado:true,expiraEm:expira,
          destinatarioPermitidoE164:destinoPermitido,relogio:()=>new Date()
        },{
          atendimentoId,destinoE164:dados.destino,parametros:dados.parametros,
          templateAprovadoNome:NOME_TEMPLATE_HML
        },{
          preparar:p=>rpc('preparar_convite',{p_atendimento:p.atendimentoId,p_preparo:p.preparoId,
            p_hash_confirmar:p.hashConfirmar,p_hash_remarcar:p.hashRemarcar}),
          async validarPreparo(preparoId){
            const atual=await contexto(preparoId)
            return atual.status==='ok'&&atual.destino===dados.destino&&
              JSON.stringify(atual.parametros)===JSON.stringify(dados.parametros)
          },
          async enviar(corpo){
            const r=await enviar(corpo)
            return {httpStatus:r.httpStatus,messageId:r.wamid}
          },
          vincular:p=>rpc('vincular_convite_aceito',{p_preparo:p.preparoId,p_meta_message_id:p.messageId}),
          abandonar:p=>rpc('abandonar_preparo',{p_preparo:p.preparoId})
        })
        return resposta(resultado.estado==='vinculado'?200:409,resultado,origem)
      }catch{return resposta(503,{codigo:'CONVITE_INDISPONIVEL'},origem)}
    }

    if(body.acao==='diagnostico') {
      try {
        const r=await backend(c,'/rest/v1/rpc/mensageria_hml_diagnostico_confirmacoes',
          c.key,'POST',fetchImpl,{p_operador:c.adminId})
        if(!r.ok || r.data?.status!=='ok')return resposta(503,{codigo:'DIAGNOSTICO_INDISPONIVEL'},origem)
        const campos=[
          'convites_ativos','convites_confirmados','convites_expirados',
          'cliques_processados','remarcacoes_pendentes','respostas_aguardando',
          'respostas_prontas','respostas_reservadas','respostas_aceitas_meta',
          'respostas_recusadas_meta','respostas_indeterminadas',
          'templates_meta_cadastrados','agendamentos_hml',
        ] as const
        const resultado:Record<string,unknown>={}
        for(const campo of campos) {
          const valor=r.data[campo]
          if(typeof valor!=='number'||!Number.isSafeInteger(valor)||valor<0)
            return resposta(503,{codigo:'DIAGNOSTICO_INVALIDO'},origem)
          resultado[campo]=valor
        }
        return resposta(200,{
          ...resultado,ambiente:'homologacao',processamento_habilitado:
            (await operacao()).processamento===true,
          envio_automatico_habilitado:false,
        },origem)
      }catch{return resposta(503,{codigo:'DIAGNOSTICO_INDISPONIVEL'},origem)}
    }
    if(body.acao==='processar_lote'||ciclo) {
      // Execução separada do consumidor antigo. Desativada até autorização e E2E.
      if(controles?.processamento!==true)
        return resposta(503,{codigo:'PROCESSAMENTO_DESATIVADO'},origem)
      const limite=body.limite===undefined?(ciclo?1:5):body.limite
      if(typeof limite!=='number'||!Number.isInteger(limite)||limite<1||limite>10)
        return resposta(400,{codigo:'LIMITE_INVALIDO'},origem)
      try{
        const lista=await backend(c,'/rest/v1/rpc/mensageria_hml_listar_cliques_pendentes',
          c.key,'POST',fetchImpl,{p_operador:c.adminId,p_limite:limite})
        if(!lista.ok||lista.data?.status!=='ok'||!Array.isArray(lista.data?.itens)||
            lista.data.itens.length>limite||
            !lista.data.itens.every((id:unknown)=>typeof id==='string'&&uuid.test(id)))
          return resposta(503,{codigo:'FILA_INDISPONIVEL'},origem)
        const contagem:Record<string,number>={}
        let erros=0
        for(const itemId of lista.data.itens as string[]){
          try{
            const resultado=await backend(c,'/rest/v1/rpc/mensageria_hml_processar_clique_operacao',
              c.key,'POST',fetchImpl,{p_item:itemId,p_operador:c.adminId})
            if(!resultado.ok||typeof resultado.data?.status!=='string'){
              erros++;continue
            }
            const status=resultado.data.status as string
            if(!new Set(['confirmado','remarcacao_pendente','ja_processado',
              'ignorado','rejeitado','expirado','conflito','ja_resolvido','desativado']).has(status)){
              erros++;continue
            }
            contagem[status]=(contagem[status]??0)+1
          }catch{erros++}
        }
        // A RPC de clique já terminou a transação antes de consultar a outbox.
        const despacho=ciclo?await despachar():null
        return resposta(erros>0?503:200,{
          codigo:erros>0?'LOTE_PARCIAL':'LOTE_CONCLUIDO',
          ...(ciclo?{despacho}:{}),
          encontrados:lista.data.itens.length,erros,contagem,
          envio_automatico_habilitado:despacho!==null
        },origem)
      }catch{return resposta(503,{codigo:'FILA_INDISPONIVEL'},origem)}
    }
    if(body.acao==='processar_item') {
      if(controles?.processamento!==true)
        return resposta(503,{codigo:'PROCESSAMENTO_DESATIVADO'},origem)
      if(typeof body.itemId!=='string'||!uuid.test(body.itemId))
        return resposta(400,{codigo:'ITEM_INVALIDO'},origem)
      try {
        const r=await backend(c,'/rest/v1/rpc/mensageria_hml_processar_clique_operacao',
          c.key,'POST',fetchImpl,{p_item:body.itemId,p_operador:c.adminId})
        if(!r.ok || typeof r.data?.status!=='string')return resposta(503,{codigo:'PROCESSAMENTO_INDETERMINADO'},origem)
        const statuses=new Set(['confirmado','remarcacao_pendente','ja_processado',
          'ignorado','rejeitado','expirado','conflito','ja_resolvido','desativado'])
        if(!statuses.has(r.data.status))return resposta(503,{codigo:'RESULTADO_INVALIDO'},origem)
        return resposta(200,{status:r.data.status,codigo:typeof r.data.codigo==='string'?r.data.codigo:null},origem)
      }catch{return resposta(503,{codigo:'PROCESSAMENTO_INDETERMINADO'},origem)}
    }
    return resposta(400,{codigo:'ACAO_INVALIDA'},origem)
  }
}

import {ESCOPO_META_HML} from './escopoMetaHml.ts'

type Env = {get(name:string):string|undefined}
type Objeto = Record<string,unknown>
const {projeto,wabaId,phoneNumberId,appId,versaoGraph}=ESCOPO_META_HML
const base='https://graph.facebook.com/'+versaoGraph

function objeto(valor:unknown):Objeto|null{
  return valor!==null&&typeof valor==='object'&&!Array.isArray(valor)?valor as Objeto:null
}

export async function prevalidarMetaHml(env:Env,requisitar:typeof fetch){
  const token=env.get('HML_META_TEST_ACCESS_TOKEN')??''
  const configurada=env.get('HML_PROJECT_REF')===projeto&&
    env.get('SUPABASE_URL')==='https://'+projeto+'.supabase.co'&&
    /^[A-Za-z0-9_.|~-]{32,4096}$/.test(token)
  async function ler(path:string){
    if(!configurada)return null
    try{
      const r=await requisitar(base+path,{
        method:'GET',redirect:'error',signal:AbortSignal.timeout(8000),
        headers:{authorization:'Bearer '+token,accept:'application/json'}
      })
      return r.ok?objeto(await r.json()):null
    }catch{return null}
  }
  const [telefone,lista,permissoes,app]=await Promise.all([
    ler('/'+phoneNumberId+'?fields=id'),
    ler('/'+wabaId+'/phone_numbers?fields=id&limit=100'),
    ler('/me/permissions?limit=100'),
    ler('/app?fields=id')
  ])
  const acessoTelefone=telefone?.id===phoneNumberId
  const vinculoWaba=Array.isArray(lista?.data)&&lista.data.some(item=>objeto(item)?.id===phoneNumberId)
  function permissao(nome:string){
    if(!Array.isArray(permissoes?.data))return null
    const item=permissoes.data.map(objeto).find(p=>p?.permission===nome)
    return item?item.status==='granted':objeto(permissoes.paging)?.next?null:false
  }
  return {
    credencial_configurada:configurada,
    credencial_aceita:acessoTelefone||vinculoWaba,
    telefone_acessivel:acessoTelefone,
    telefone_na_waba:vinculoWaba,
    aplicativo_hml:typeof app?.id==='string'?app.id===appId:null,
    permissao_gestao:permissao('whatsapp_business_management'),
    permissao_envio:permissao('whatsapp_business_messaging')
  }
}

/**
 * Orquestrador backend — convite com dois botões.
 * Dependências são injetadas para permitir testes SEM chamadas à Meta.
 *
 * AVISO: este módulo não está conectado à Edge Function pública.
 * Antes de ligar o transporte, exigir confirmação de template APPROVED
 * na Meta, fonte autoritativa dos dados e autorização de envio de curta duração.
 */
import {wamidValidoHml} from './validarWamidHml.ts'
import {prepararTemplateConfirmacaoHml,type CorpoTemplateMeta} from './templateConfirmacao.ts'
import {NOME_TEMPLATE_HML} from './solicitacaoTemplateMeta.ts'
const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
export type RegistroPreparo={
  status:'preparado'|'ja_preparado'|'conflito'|'rejeitado'
  convite_id?:string
}
export type RespostaTransporte={httpStatus:number;messageId?:string|null}
export type OperacoesConvite={
  preparar(input:{
    atendimentoId:string;preparoId:string;hashConfirmar:string;hashRemarcar:string
  }):Promise<RegistroPreparo>
  validarPreparo?(preparoId:string):Promise<boolean>
  enviar(corpo:CorpoTemplateMeta):Promise<RespostaTransporte>
  vincular(input:{preparoId:string;messageId:string}):Promise<{status:string}>
  abandonar(input:{preparoId:string}):Promise<{status:string}>
}
export type ContextoConvite={
  // Deverá ser produzido por consulta SQL no backend, nunca enviado pelo browser.
  atendimentoId:string
  destinoE164:string
  parametros:readonly string[]
  templateAprovadoNome:string
}
export type AutorizacaoHml={
  projectRef:string
  envioHabilitado:boolean
  expiraEm:string|null
  destinatarioPermitidoE164:string
  relogio:()=>Date
}
export type EstadoEnvioConvite=
 'bloqueado'|'preparo_rejeitado'|'preparo_repetido'|'meta_rejeitada'|
 'resultado_indeterminado'|'aceito_sem_vinculo'|'vinculado'

export async function orquestrarConviteHml(
  auth:AutorizacaoHml,ctx:ContextoConvite,ops:OperacoesConvite,
):Promise<{estado:EstadoEnvioConvite;codigo:string}> {
  const resto=auth.expiraEm?Date.parse(auth.expiraEm)-auth.relogio().getTime():NaN
  if(auth.projectRef!==REF || auth.envioHabilitado!==true ||
     !Number.isFinite(resto)||resto<=0||resto>180_000) {
    return {estado:'bloqueado',codigo:'SEM_JANELA_DE_TESTE'}
  }
  if(!UUID.test(ctx.atendimentoId) ||
     ctx.templateAprovadoNome!==NOME_TEMPLATE_HML){
    return {estado:'bloqueado',codigo:'CONTEXTO_OU_TEMPLATE_NAO_APROVADO'}
  }
  // Testa o número exato antes de qualquer transação ou HTTP.
  let template:Awaited<ReturnType<typeof prepararTemplateConfirmacaoHml>>
  try{
    template=await prepararTemplateConfirmacaoHml({
      destinoE164:ctx.destinoE164,
      permitidoE164:auth.destinatarioPermitidoE164,
      templateNome:ctx.templateAprovadoNome,
      idioma:'pt_BR',
      parametros:ctx.parametros
    })
  }catch{
    return {estado:'bloqueado',codigo:'DESTINO_OU_TEMPLATE_INVALIDO'}
  }
  const preparoId=crypto.randomUUID()
  let preparo:RegistroPreparo
  try{
    preparo=await ops.preparar({
      atendimentoId:ctx.atendimentoId,
      preparoId,
      hashConfirmar:template.hashConfirmar,
      hashRemarcar:template.hashRemarcar
    })
  }catch{
    return {estado:'preparo_rejeitado',codigo:'RESERVA_INDISPONIVEL'}
  }
  if(preparo.status==='ja_preparado')
    return {estado:'preparo_repetido',codigo:'NAO_REENVIAR_PREPARO_EXISTENTE'}
  if(preparo.status!=='preparado'||!preparo.convite_id||!UUID.test(preparo.convite_id))
    return {estado:'preparo_rejeitado',codigo:'PREPARO_NAO_CONFIRMADO'}

  if(ops.validarPreparo&&!await ops.validarPreparo(preparoId).catch(()=>false)){
    await ops.abandonar({preparoId}).catch(()=>null)
    return {estado:'preparo_rejeitado',codigo:'AGENDAMENTO_ALTERADO_ANTES_DO_ENVIO'}
  }

  // Depois de uma chamada à Meta, resposta perdida significa envio INDETERMINADO.
  // Nunca repetir automaticamente neste cenário — um segundo POST duplicaria
  // o convite e os segredos gerados na chamada anterior seriam perdidos.
  // Segunda verificação imediatamente antes de cada POST externo.
  // Se a reserva demorou, não basta a autorização válida no início da operação.
  const restanteAntesDoPost=auth.expiraEm
    ? Date.parse(auth.expiraEm)-auth.relogio().getTime():NaN
  if(!Number.isFinite(restanteAntesDoPost) ||
      restanteAntesDoPost<=0 || restanteAntesDoPost>180_000){
    await ops.abandonar({preparoId}).catch(()=>null)
    return {estado:'bloqueado',codigo:'JANELA_DE_TESTE_ENCERROU_ANTES_DO_ENVIO'}
  }
  let meta:RespostaTransporte
  try{
    meta=await ops.enviar(template.corpoApi)
  }catch{
    return {estado:'resultado_indeterminado',codigo:'META_RESPOSTA_INCERTA_NAO_REENVIAR'}
  }
  if(meta.httpStatus>=400&&meta.httpStatus<500){
    // Resposta explícita de recusa do servidor: tente encerrar preparo.
    await ops.abandonar({preparoId}).catch(()=>null)
    return {estado:'meta_rejeitada',codigo:'META_REJEITOU_TEMPLATE'}
  }
  if(meta.httpStatus<200||meta.httpStatus>=300||!meta.messageId||
     !wamidValidoHml(meta.messageId)){
    return {estado:'resultado_indeterminado',codigo:'META_ACEITE_NAO_CONFIRMADO'}
  }
  // Aceite Meta NÃO significa agendamento confirmado. Apenas vincula convite.
  try{
    const vinculo=await ops.vincular({preparoId,messageId:meta.messageId})
    if(vinculo.status==='vinculado'||vinculo.status==='ja_vinculado')
      return {estado:'vinculado',codigo:'CONVITE_PRONTO_PARA_CLIQUE'}
    return {estado:'aceito_sem_vinculo',codigo:'META_ACEITOU_MAS_VINCULO_PENDENTE'}
  }catch{
    return {estado:'aceito_sem_vinculo',codigo:'META_ACEITOU_MAS_BANCO_INDISPONIVEL'}
  }
}

// Preserva o ID opaco da Meta, inclusive o padding Base64 no fim.
export function wamidValidoHml(valor:unknown):valor is string{
  return typeof valor==='string'&&valor.length>=10&&valor.length<=300&&
    /^wamid\.[A-Za-z0-9+/_.-]{4,}={0,2}$/.test(valor)&&!/[\r\n]/.test(valor)
}

/**
 * Montagem PURA de template utilitário com 2 quick replies da Meta.
 * Exclusivamente para utilização no backend. Este módulo:
 * - não lê chaves da Meta nem faz HTTP;
 * - não envia mensagem e não cadastra convite;
 * - gera tokens criptograficamente aleatórios, que só devem ser usados
 *   na chamada Cloud API e armazenados no banco em hash SHA-256.
 *
 * Importante: os botões "Confirmar" e "Remarcar" e os parâmetros de body
 * devem coincidir com o TEMPLATE APROVADO pela Meta.
 */
export type TemplateConfirmacaoEntrada = {
  destinoE164: string
  permitidoE164: string
  templateNome: string
  idioma: 'pt_BR'
  parametros: readonly string[]
}
export type CorpoTemplateMeta = {
  messaging_product: 'whatsapp'
  to: string
  type: 'template'
  template: {
    name: string
    language:{code:'pt_BR'}
    components: Array<
      {type:'body'; parameters:Array<{type:'text';text:string}>} |
      {type:'button';sub_type:'quick_reply';index:'0'|'1';
       parameters:[{type:'payload';payload:string}]}
    >
  }
}
export type ConvitePreparadoBackend = {
  corpoApi: CorpoTemplateMeta
  segredoConfirmar: string
  segredoRemarcar: string
  hashConfirmar: string
  hashRemarcar: string
}
const TEL = /^\+55[1-9][0-9][2-9][0-9]{7,8}$/
const NOME = /^[a-z][a-z0-9_]{2,100}$/
function numeroNormalizado(valor:string){return valor.replace(/^\+/,'')}
async function sha256(s:string){
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))
  return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')
}
export async function prepararTemplateConfirmacaoHml(
  dados:TemplateConfirmacaoEntrada,
):Promise<ConvitePreparadoBackend> {
  if(!TEL.test(dados.destinoE164) ||
     numeroNormalizado(dados.destinoE164)!==numeroNormalizado(dados.permitidoE164))
    throw Error('DESTINATARIO_NAO_AUTORIZADO')
  if(!NOME.test(dados.templateNome)||dados.idioma!=='pt_BR')throw Error('TEMPLATE_INVALIDO')
  if(dados.parametros.length>8 || dados.parametros.some(p=>typeof p!=='string'||!p.trim()||p.length>255))
    throw Error('PARAMETROS_INVALIDOS')
  const segredoConfirmar='KPAG1_'+crypto.randomUUID()
  const segredoRemarcar='KPAG1_'+crypto.randomUUID()
  if(segredoConfirmar===segredoRemarcar)throw Error('ENTROPIA_INSUFICIENTE')
  const hashConfirmar=await sha256(segredoConfirmar)
  const hashRemarcar=await sha256(segredoRemarcar)
  const components:CorpoTemplateMeta['template']['components']=[]
  if(dados.parametros.length)components.push({
    type:'body',parameters:dados.parametros.map(text=>({type:'text',text}))
  })
  components.push({
    type:'button',sub_type:'quick_reply',index:'0',
    parameters:[{type:'payload',payload:segredoConfirmar}]
  },{
    type:'button',sub_type:'quick_reply',index:'1',
    parameters:[{type:'payload',payload:segredoRemarcar}]
  })
  return {
    corpoApi:{messaging_product:'whatsapp',to:numeroNormalizado(dados.destinoE164),
      type:'template',template:{name:dados.templateNome,language:{code:'pt_BR'},components}},
    segredoConfirmar,segredoRemarcar,hashConfirmar,hashRemarcar
  }
}

/**
 * Solicitação de TEMPLATE Meta (utility) — preparação sem envio.
 * Deve ser revisado no Gerenciador do WhatsApp/Meta antes de submissão.
 * A posição dos botões deve coincidir com o payload de envio:
 *   0 = Confirmar; 1 = Remarcar.
 * NÃO submete nada à API, NÃO cria template por conta própria.
 */
export type TemplateParaAprovacao = {
  name:string
  language:'pt_BR'
  category:'UTILITY'
  parameter_format:'POSITIONAL'
  components:Array<
    {type:'BODY';text:string;example:{body_text:string[][]}} |
    {type:'BUTTONS';buttons:Array<{type:'QUICK_REPLY';text:string}>}
  >
}
export const NOME_TEMPLATE_HML='kaza_confirmacao_agendamento_hml'
export function prepararSolicitacaoTemplateMeta():TemplateParaAprovacao {
  return {
    name:NOME_TEMPLATE_HML,
    language:'pt_BR',
    category:'UTILITY',
    parameter_format:'POSITIONAL',
    components:[
      {type:'BODY',
        text:'Olá, {{1}}! 🐾\n\nO banho de {{2}} está agendado para {{3}} às {{4}} na KAZA PET.\n\nPodemos confirmar esse horário?',
        example:{body_text:[['Mariana','Thor','24/11/2026','09:00']]}},
      {type:'BUTTONS',buttons:[
        {type:'QUICK_REPLY',text:'Confirmar'},
        {type:'QUICK_REPLY',text:'Remarcar'}
      ]}
    ]
  }
}

/**
 * Transporte para um único agradecimento HML WhatsApp Cloud API.
 *
 * É um adaptador isolado para testes com fetch injetado:
 * NÃO é importado pela Edge mensageria-outbox-hml v1.
 * NÃO registra corpo, token, telefone, headers ou resposta bruta em logs.
 * SEM retry automático. A decisão de reservar/finalizar pertence à outbox.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {NOME_TEMPLATE_HML} from '../mensageria-confirmacao-hml/solicitacaoTemplateMeta.ts'
import type {CorpoTemplateMeta} from '../mensageria-confirmacao-hml/templateConfirmacao.ts'
import type {EnvioTextoMeta} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

import { ESCOPO_META_HML } from '../mensageria-confirmacao-hml/escopoMetaHml.ts'

const HML=ESCOPO_META_HML.projeto
const HML_URL='https://'+HML+'.supabase.co'
const META_PHONE_HML=ESCOPO_META_HML.phoneNumberId
const GRAPH='https://graph.facebook.com/'+ESCOPO_META_HML.versaoGraph+'/'+META_PHONE_HML+'/messages'
const DESTINO=/^55[1-9][0-9]{9,10}$/

export type AmbienteMetaHml={get:(name:string)=>string|undefined}
export type ResultadoMetaHml={httpStatus:number;wamid:string|null}
export type OpcoesTransporteHml={
  ambiente:AmbienteMetaHml
  requisitar?:(url:string,init:RequestInit)=>Promise<Response>
  agora?:()=>number
}

function permitido(env:AmbienteMetaHml,agora:number):{destino:string;token:string}|null{
  if(env.get('HML_PROJECT_REF')!==HML||
     env.get('SUPABASE_URL')!==HML_URL||
     env.get('HML_CONFIRMATION_REAL_SEND_ENABLED')!=='true'||
     env.get('HML_META_TEST_WABA_ID')!==ESCOPO_META_HML.wabaId||
     env.get('HML_META_TEST_APP_ID')!==ESCOPO_META_HML.appId||
     env.get('HML_META_TEST_PHONE_NUMBER_ID')!==META_PHONE_HML||
     env.get('HML_OUTBOX_SEND_ENABLED')!=='true')return null
  const fim=Date.parse(env.get('HML_OUTBOX_SEND_EXPIRES_AT')??'')
  if(!Number.isFinite(agora)||!Number.isFinite(fim)||
     fim<=agora||fim-agora>180_000)return null
  const destino=env.get('HML_TEST_RECIPIENT_E164')??''
  const token=env.get('HML_META_TEST_ACCESS_TOKEN')??''
  if(!DESTINO.test(destino)||token.length<32||token.length>4096||
     /[\r\n]/.test(token))return null
  return {destino,token}
}
export function envioMetaHmlHabilitado(env:AmbienteMetaHml):boolean{
  return permitido(env,Date.now())!==null
}
function corpoValido(c:EnvioTextoMeta,destino:string):boolean {
  return c?.messaging_product==='whatsapp'&&
    c.recipient_type==='individual'&&
    c.to===destino&&c.type==='text'&&
    c.text?.preview_url===false&&
    typeof c.text?.body==='string'&&
    c.text.body.trim().length>=1&&c.text.body.length<=4096&&
    typeof c.context?.message_id==='string'&&
    wamidValidoHml(c.context.message_id)
}

export function criarTransporteMetaHml({ambiente,requisitar=fetch,agora=Date.now}:OpcoesTransporteHml){
  return async (body:EnvioTextoMeta|CorpoTemplateMeta):Promise<ResultadoMetaHml>=>{
    const cfg=permitido(ambiente,agora())
    if(!cfg)throw new Error('ENVIO_META_HML_NAO_AUTORIZADO')
    if(body?.type==='template'
      ? body.to!==cfg.destino||body.messaging_product!=='whatsapp'||
        body.template.name!==NOME_TEMPLATE_HML||body.template.language.code!=='pt_BR'
      : !corpoValido(body,cfg.destino))throw new Error('MENSAGEM_META_HML_INVALIDA')
    // Confere a janela uma segunda vez imediatamente antes do POST.
    const atual=permitido(ambiente,agora())
    if(!atual||atual.destino!==cfg.destino||atual.token!==cfg.token)
      throw new Error('AUTORIZACAO_EXPIRADA')
    let res:Response
    try{
      res=await requisitar(GRAPH,{
        method:'POST',redirect:'error',signal:AbortSignal.timeout(12000),
        headers:{authorization:'Bearer '+cfg.token,'content-type':'application/json'},
        body:JSON.stringify(body)
      })
    }catch{
      // A Meta pode ter aceitado antes de ocorrer timeout, queda de rede
      // ou redirecionamento. É proibido repetir automaticamente a chamada.
      throw new Error('META_RESPOSTA_INDETERMINADA')
    }
    if(!Number.isInteger(res.status)||res.status<200||res.status>599)
      return {httpStatus:503,wamid:null}
    if(res.status<200||res.status>=300)return {httpStatus:res.status,wamid:null}
    let parsed:unknown
    try{parsed=await res.json()}catch{
      return {httpStatus:res.status,wamid:null}
    }
    if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))
      return {httpStatus:res.status,wamid:null}
    const response=parsed as {
      messaging_product?:unknown
      contacts?:{input?:unknown;wa_id?:unknown}[]
      messages?:{id?:unknown}[]
    }
    const id=response.messages?.[0]?.id
    // contacts[].wa_id pode ser diferente da entrada (nono dígito BR).
    // contacts[].input, quando presente, precisa refletir o destino pedido.
    if(response.messaging_product!=='whatsapp'||
       (Array.isArray(response.contacts)&&
         (response.contacts[0]?.input!==cfg.destino))||
       !Array.isArray(response.messages)||
       typeof id!=='string'||!wamidValidoHml(id))
      return {httpStatus:res.status,wamid:null}
    return {httpStatus:res.status,wamid:id}
  }
}

/**
 * KAZA PET • adapter RPC da outbox de agradecimentos HML.
 *
 * APENAS para execução injetada/testes. NÃO importado na Edge publicada.
 * Sem chamadas de Graph API, sem agendamento, sem acesso do navegador.
 * Nenhum método acessa a rede quando HML_OUTBOX_RPC_ENABLED !== 'true'.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import type {OperacoesDespachoHml} from './orquestradorDespachoHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const BASE='https://'+REF+'.supabase.co'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const E164=/^\+55[1-9][0-9]{9,10}$/
const ESTADOS_RESERVA=new Set([
 'reservado','ja_reservado','nao_pronto','agenda_invalida',
 'janela_inbound_indisponivel','outro'
])
const ESTADOS_FINAL=new Set(['aceito_meta','recusado_meta','indeterminado'])
const CODIGO=/^[A-Z][A-Z0-9_]{1,63}$/
const RPCS={
  listar:'mensageria_hml_outbox_listar_pendentes',
  reservar:'mensageria_hml_outbox_reservar',
  contexto:'mensageria_hml_outbox_contexto',
  finalizar:'mensageria_hml_outbox_finalizar'
} as const
type Env={get:(nome:string)=>string|undefined}
type Fetch=(url:string,init:RequestInit)=>Promise<Response>
type Envio=OperacoesDespachoHml['enviar']

export type ConfigAdaptadorRpcHml={
  ambiente:Env
  requisitar:Fetch // obrigatório: teste sempre injetado, sem fallback implícito
  enviar:Envio // transporte injetado; não importamos Meta aqui
}
export type RpcOutboxHml=OperacoesDespachoHml & {
  /** Retorna apenas se o ambiente indica HML e a flag de RPC está ligada */
  configurado:()=>boolean
}
export function criarAdaptadorRpcOutboxHml({
  ambiente,requisitar,enviar
}:ConfigAdaptadorRpcHml):RpcOutboxHml{
  const permitido=()=>{
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')??''
    const operator=ambiente.get('HML_OPERATOR_UUID')??''
    return ambiente.get('SUPABASE_URL')===BASE&&
      ambiente.get('HML_PROJECT_REF')===REF&&
      ambiente.get('HML_OUTBOX_RPC_ENABLED')==='true'&&
      secret.length>=32&&secret.length<=8192&&!/[\r\n]/.test(secret)&&
      UUID.test(operator)&&typeof requisitar==='function'&&
      typeof enviar==='function'
  }
  const rpc=async (
    acao:keyof typeof RPCS, corpo:Record<string,unknown>
  ):Promise<Record<string,unknown>>=>{
    if(!permitido())throw Error('RPC_HML_DESATIVADA')
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')!
    let resposta:Response
    try {
      resposta=await requisitar(BASE+'/rest/v1/rpc/'+RPCS[acao],{
        method:'POST',redirect:'error',
        headers:{
          apikey:secret,authorization:'Bearer '+secret,
          'content-type':'application/json'
        },
        body:JSON.stringify(corpo),
        signal:AbortSignal.timeout(12000)
      })
    }catch{throw Error('RPC_HML_RESPOSTA_INDISPONIVEL')}
    if(!resposta.ok)throw Error('RPC_HML_REJEITADA')
    let data:unknown
    try{data=await resposta.json()}catch{
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    }
    if(!data||typeof data!=='object'||Array.isArray(data))
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    return data as Record<string,unknown>
  }
  const autorizado=(id:string)=>UUID.test(id)&&
    id===ambiente.get('HML_OPERATOR_UUID')
  return {
    configurado:permitido,
    async listar(limite){
      if(!Number.isInteger(limite)||limite<1||limite>10)
        throw Error('LIMITE_RPC_INVALIDO')
      const op=ambiente.get('HML_OPERATOR_UUID')??''
      if(!autorizado(op))throw Error('OPERADOR_RPC_INVALIDO')
      const r=await rpc('listar',{p_operador:op,p_limite:limite})
      if(r.status!=='ok'||!Array.isArray(r.itens)||
         typeof r.quantidade!=='number'||!Number.isInteger(r.quantidade)||
         r.quantidade!==r.itens.length||
         r.itens.length>limite||
         !r.itens.every(id=>typeof id==='string'&&UUID.test(id)))
        throw Error('FILA_RPC_INCONSISTENTE')
      return {status:'ok',itens:r.itens,quantidade:r.quantidade as number}
    },
    async reservar({outboxId,chave,operadorId}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId))
        throw Error('RESERVA_RPC_INVALIDA')
      const r=await rpc('reservar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId
      })
      if(typeof r.status!=='string'||!ESTADOS_RESERVA.has(r.status))
        throw Error('RESERVA_RPC_INDETERMINADA')
      return {status:r.status as Awaited<ReturnType<OperacoesDespachoHml['reservar']>>['status']}
    },
    async contexto({p_outbox,p_chave,p_operador,p_destinatario_permitido}){
      if(!UUID.test(p_outbox)||!UUID.test(p_chave)||
        !autorizado(p_operador)||!E164.test(p_destinatario_permitido)||
        p_destinatario_permitido!=='+'
          +(ambiente.get('HML_TEST_RECIPIENT_E164')??''))
        throw Error('CONTEXTO_RPC_NAO_AUTORIZADO')
      const resposta=await rpc('contexto',{
        p_outbox,p_chave,p_operador,p_destinatario_permitido
      })
      if(typeof resposta.status!=='string')
        throw Error('CONTEXTO_RPC_INVALIDO')
      return resposta
    },
    async finalizar({outboxId,chave,operadorId,resultado,wamid,codigo}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId)||
        !ESTADOS_FINAL.has(resultado))
        throw Error('FINALIZACAO_RPC_INVALIDA')
      if(resultado==='aceito_meta'){
        if(typeof wamid!=='string'||!wamidValidoHml(wamid)||codigo!==null)
          throw Error('ACEITE_RPC_INVALIDO')
      }else{
        if(wamid!==null||typeof codigo!=='string'||!CODIGO.test(codigo))
          throw Error('MOTIVO_RPC_INVALIDO')
      }
      const r=await rpc('finalizar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId,
        p_resultado:resultado,p_wamid:wamid,p_codigo:codigo
      })
      if(typeof r.status!=='string'||r.status.length>80)
        throw Error('FINALIZACAO_RPC_RESPOSTA_INVALIDA')
      return {status:r.status}
    },
    async enviar(corpo){
      if(!permitido())throw Error('RPC_HML_DESATIVADA')
      return enviar(corpo)
    }
  }
}

/**
 * KAZA PET • Mensageria • HML
 * Plano de despacho da outbox: composição de RPCs autoritativas e transportador injetado.
 *
 * NÃO IMPORTADO pela Edge publicada. NÃO FAZ rede diretamente.
 * Nunca aceitar parâmetros comerciais, telefone ou texto do navegador.
 * Ativar somente após revisão e homologação E2E de um envio Meta real.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {
  montarRespostaDaOutbox,
  type ConsultarContexto,
} from '../mensageria-confirmacao-hml/contextoOutboxBackendHml.ts'
import type {
  EnvioTextoMeta,
} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const DESTINO=/^55[1-9][0-9]{9,10}$/
type EstadoReserva='reservado'|'ja_reservado'|'nao_pronto'|'agenda_invalida'|'janela_inbound_indisponivel'|'outro'
type Finalizacao='aceito_meta'|'recusado_meta'|'indeterminado'

export type ConfigDespachoHml={
  projeto:string
  operadorId:string
  permitidoE164:string // Secret do servidor, sem '+'
  envioHabilitado:boolean
  autorizacaoExpiraIso:string|null
  agora:()=>Date
  chaveAleatoria:()=>string
}
export type OperacoesDespachoHml={
  listar(limite:number):Promise<{status:string;itens:unknown[];quantidade:number}>
  reservar(input:{outboxId:string;chave:string;operadorId:string}):Promise<{status:EstadoReserva}>
  contexto:ConsultarContexto
  enviar(corpo:EnvioTextoMeta):Promise<{httpStatus:number;wamid?:string|null}>
  finalizar(input:{
    outboxId:string;chave:string;operadorId:string;
    resultado:Finalizacao;wamid:string|null;codigo:string|null
  }):Promise<{status:string}>
}
export type ResultadoDespachoHml={
  estado:'bloqueado'|'fila_vazia'|'concorrencia'|'preparo_bloqueado'|
    'indeterminado'|'recusado'|'aceito'|'aceito_sem_registro'
  codigo:string
  aceitosMeta:number
  entregues:number
}

function validacao(cfg:ConfigDespachoHml):boolean{
  const t=cfg.agora().getTime()
  const expira=cfg.autorizacaoExpiraIso?Date.parse(cfg.autorizacaoExpiraIso):NaN
  return cfg.projeto===REF&&cfg.envioHabilitado===true&&UUID.test(cfg.operadorId)&&
    DESTINO.test(cfg.permitidoE164)&&Number.isFinite(t)&&Number.isFinite(expira)&&
    expira>t&&expira-t<=180000
}
export async function executarUmAgradecimentoHml(
  cfg:ConfigDespachoHml,ops:OperacoesDespachoHml
):Promise<ResultadoDespachoHml>{
  const resultado=(estado:ResultadoDespachoHml['estado'],codigo:string):ResultadoDespachoHml=>
    ({estado,codigo,aceitosMeta:0,entregues:0})
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_DE_ENVIO_AUSENTE')
  let itens:unknown[]
  try{
    const fila=await ops.listar(1)
    if(fila.status!=='ok'||!Array.isArray(fila.itens)||
       fila.itens.length>1||fila.quantidade!==fila.itens.length||
       !fila.itens.every(x=>typeof x==='string'&&UUID.test(x)))
      return resultado('bloqueado','FILA_INCONSISTENTE')
    itens=fila.itens
  }catch{return resultado('bloqueado','FILA_INDISPONIVEL')}
  if(itens.length===0)return resultado('fila_vazia','NENHUMA_RESPOSTA_ELEGIVEL')
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_VENCIDA')

  const outboxId=itens[0] as string
  const chave=cfg.chaveAleatoria()
  if(!UUID.test(chave))return resultado('bloqueado','CHAVE_NAO_VALIDA')
  let reservado:{status:EstadoReserva}
  try{
    reservado=await ops.reservar({outboxId,chave,operadorId:cfg.operadorId})
  }catch{return resultado('bloqueado','RESERVA_NAO_CONFIRMADA')}
  if(reservado.status!=='reservado')
    return resultado('concorrencia','NENHUM_REENVIO_AUTORIZADO')

  const finalizar=async(tipo:Finalizacao,codigo:string|null,wamid:string|null)=>{
    try{
      return (await ops.finalizar({
        outboxId,chave,operadorId:cfg.operadorId,
        resultado:tipo,codigo,wamid
      })).status===tipo
    }catch{return false}
  }

  // A consulta RPC autoritativa verifica convite + webhook assinado +
  // banco/agenda + modelo publicado + clique dentro da janela Meta de 24h.
  const montado=await montarRespostaDaOutbox({
    projeto:cfg.projeto,
    outboxId,chaveTentativa:chave,operadorId:cfg.operadorId,
    destinatarioPermitidoE164:'+'+cfg.permitidoE164
  },ops.contexto)
  if(montado.status!=='pronto'){
    // Sem POST Meta. Mantém tentativa única para análise manual; não reabrir fila.
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','CONTEUDO_OU_CONTEXTO_NAO_ELEGIVEL')
  }
  if(montado.corpo.to!==cfg.permitidoE164||!validacao(cfg)){
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','AUTORIZACAO_EXPIRADA_OU_DESTINO_INCORRETO')
  }
  let meta:{httpStatus:number;wamid?:string|null}
  try{
    meta=await ops.enviar(montado.corpo)
  }catch{
    await finalizar('indeterminado','META_TIMEOUT',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  // HTTP 4xx explícito é recusa. 5xx, 2xx sem wamid e demais são incertos.
  if(Number.isInteger(meta.httpStatus)&&meta.httpStatus>=400&&meta.httpStatus<500){
    await finalizar('recusado_meta','META_HTTP_'+meta.httpStatus,null)
    return resultado('recusado','META_RECUSOU')
  }
  if(meta.httpStatus!==200&&meta.httpStatus!==201||
     !meta.wamid||!wamidValidoHml(meta.wamid)){
    await finalizar('indeterminado','META_ACEITE_INDETERMINADO',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  const salvo=await finalizar('aceito_meta',null,meta.wamid)
  if(!salvo)return resultado('aceito_sem_registro','ACEITE_META_RECONCILIACAO_MANUAL')
  return {estado:'aceito',codigo:'META_ACEITOU_NAO_E_ENTREGA',aceitosMeta:1,entregues:0}
}

/**
 * Liga RPC autoritativa ao gerador de texto; ainda SEM transporte Meta.
 *
 * Somente backend HML deve executar esta função. Os IDs e a allowlist chegam
 * do backend autenticado/secret manager, nunca do navegador.
 * A RPC SQL é restrita a service_role e exige outbox previamente reservada.
 */
import {prepararAgradecimentoHml,type ContextoRespostaHml,
  type PreparacaoRespostaHml} from './respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
type Config={
  projeto:string
  outboxId:string
  chaveTentativa:string
  operadorId:string
  destinatarioPermitidoE164:string
}
type ResultadoContexto = {status:string} & Record<string,unknown>
export type ConsultarContexto =
  (args:{p_outbox:string;p_chave:string;p_operador:string;p_destinatario_permitido:string})=>Promise<unknown>
export type ResultadoPreparado =
  | {status:'pronto'; corpo:Extract<PreparacaoRespostaHml,{status:'pronto'}>['corpo']}
  | {status:'bloqueado';codigo:string}

const CAMPOS=[
  'eventoCodigo','statusAtendimento','statusConvite','textoModelo',
  'destinatarioE164','remetenteClique','mensagemCliqueId',
  'inicioAtualIso','inicioConviteIso','cliqueRecebidoIso','agoraIso',
  'nomeTutor','nomePet','nomeEmpresa'
] as const

export async function montarRespostaDaOutbox(
  config:Config, consultar:ConsultarContexto
):Promise<ResultadoPreparado> {
  if(config.projeto!==REF ||
     !UUID.test(config.outboxId) ||
     !UUID.test(config.chaveTentativa) ||
     !UUID.test(config.operadorId) ||
     !/^\+55[0-9]{10,11}$/.test(config.destinatarioPermitidoE164))
    return {status:'bloqueado',codigo:'CONTEXTO_HML_NAO_AUTORIZADO'}
  let raw:unknown
  try{
    raw=await consultar({
      p_outbox:config.outboxId,
      p_chave:config.chaveTentativa,
      p_operador:config.operadorId,
      p_destinatario_permitido:config.destinatarioPermitidoE164
    })
  }catch{return {status:'bloqueado',codigo:'CONTEXTO_HML_INDISPONIVEL'}}
  if(!raw||typeof raw!=='object'||Array.isArray(raw))
    return {status:'bloqueado',codigo:'RESPOSTA_RPC_INVALIDA'}
  const r=raw as ResultadoContexto
  if(r.status!=='pronto')return {status:'bloqueado',codigo:'OUTBOX_NAO_ELEGIVEL'}
  if(r.modeloPublicado!==true||CAMPOS.some(k=>typeof r[k]!=='string'))
    return {status:'bloqueado',codigo:'DADOS_RPC_INVALIDOS'}
  if(r.destinatarioE164!==config.destinatarioPermitidoE164)
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  if(r.eventoCodigo!=='AGENDAMENTO_CONFIRMADO_WHATSAPP')
    return {status:'bloqueado',codigo:'EVENTO_NAO_HABILITADO'}
  const result=prepararAgradecimentoHml(r as unknown as ContextoRespostaHml)
  if(result.status!=='pronto')return result
  if(result.corpo.to!==config.destinatarioPermitidoE164.slice(1))
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  return result
}

/**
 * Mensagem de resposta no WhatsApp, montada SOMENTE com contexto obtido
 * e validado no backend. Não faz HTTP, não lê credenciais e não envia mensagens.
 *
 * Origem obrigatória dos dados no serviço futuro:
 * - outbox com estado aguardando_integracao/pronto e convite confirmado;
 * - dados da agenda/grupo/pet/tutor persistidos no banco;
 * - último clique inbound validado HMAC, associado a convite e wamid;
 * - modelo PUBLICADO e versionado, nunca um rascunho local do navegador.
 */
import {wamidValidoHml} from './validarWamidHml.ts'
export type EventoRespostaHml =
  | 'AGENDAMENTO_CONFIRMADO_WHATSAPP'
  | 'REMARCACAO_SOLICITADA_WHATSAPP'
export type ContextoRespostaHml = {
  eventoCodigo:EventoRespostaHml
  statusAtendimento:string
  statusConvite:string
  modeloPublicado:boolean
  textoModelo:string
  destinatarioE164:string
  remetenteClique:string
  mensagemCliqueId:string
  inicioAtualIso:string
  inicioConviteIso:string
  cliqueRecebidoIso:string
  agoraIso:string
  nomeTutor:string
  nomePet:string
  nomeEmpresa:string
}
export type EnvioTextoMeta = {
  messaging_product:'whatsapp'
  recipient_type:'individual'
  to:string
  type:'text'
  context:{message_id:string}
  text:{body:string;preview_url:false}
}
export type PreparacaoRespostaHml =
  | {status:'pronto';corpo:EnvioTextoMeta}
  | {status:'bloqueado';codigo:string}

const MARCADOR=/\{\{\s*([A-Z_0-9]+)\s*\}\}|\{\s*([A-Z_0-9]+)\s*\}/g
const TEXTO_TAG_INCONHECIDA=/{{[^{}]*}}/
const TELEFONE=/^\+55[1-9][0-9]{9,10}$/

function equivalenteWhatsApp(destino:string,origem:string):boolean {
  const normal=destino.slice(1)
  if(origem===normal)return true
  // A Meta pode reportar alguns celulares brasileiros sem o nono dígito.
  return normal.length===13&&normal[4]==='9'&&
    origem===normal.slice(0,4)+normal.slice(5)
}
function horarioLocal(data:Date):{dia:string;hora:string} {
  return {
    dia:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'
    }).format(data),
    hora:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'
    }).format(data),
  }
}
function limparNome(valor:string):string {
  return valor.trim().replace(/[\r\n\t\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').slice(0,80)
}

export function prepararAgradecimentoHml(c:ContextoRespostaHml):PreparacaoRespostaHml {
  if(!c.modeloPublicado||!c.textoModelo?.trim())return {status:'bloqueado',codigo:'MODELO_NAO_PUBLICADO'}
  if(!TELEFONE.test(c.destinatarioE164)||!equivalenteWhatsApp(c.destinatarioE164,c.remetenteClique))
    return {status:'bloqueado',codigo:'DESTINATARIO_NAO_CORRESPONDE'}
  if(!wamidValidoHml(c.mensagemCliqueId))
    return {status:'bloqueado',codigo:'MENSAGEM_ORIGINAL_INVALIDA'}
  const esperado=c.eventoCodigo==='AGENDAMENTO_CONFIRMADO_WHATSAPP'
    ? {atendimento:'confirmado',convite:'confirmado'}
    : {atendimento:'agendado',convite:'remarcacao_pendente'}
  if(c.statusAtendimento!==esperado.atendimento||c.statusConvite!==esperado.convite)
    return {status:'bloqueado',codigo:'ESTADO_DA_AGENDA_DIVERGENTE'}
  const inicio=Date.parse(c.inicioAtualIso),antes=Date.parse(c.inicioConviteIso)
  const clique=Date.parse(c.cliqueRecebidoIso),agora=Date.parse(c.agoraIso)
  if(![inicio,antes,clique,agora].every(Number.isFinite) || inicio!==antes || inicio<=agora)
    return {status:'bloqueado',codigo:'HORARIO_MODIFICADO_OU_INVALIDO'}
  // Margem de 3min para evitar tentar entregar já perto do fim da janela.
  if(clique>agora+60_000 || agora-clique>24*60*60_000-3*60_000)
    return {status:'bloqueado',codigo:'JANELA_24H_NAO_CONFIRMADA'}
  if(![c.nomeTutor,c.nomePet,c.nomeEmpresa].every(s=>typeof s==='string'&&s.trim()))
    return {status:'bloqueado',codigo:'DADOS_INCOMPLETOS'}
  const {dia,hora}=horarioLocal(new Date(inicio))
  const tags:Record<string,string>={
    NOME_TUTOR:limparNome(c.nomeTutor),NOME_PET:limparNome(c.nomePet),
    NOME_EMPRESA:limparNome(c.nomeEmpresa),
    DATA_AGENDAMENTO:dia,HORARIO_AGENDAMENTO:hora,
  }
  let desconhecida=false
  const texto=c.textoModelo.replace(MARCADOR,(_match,keyDuplo:string|undefined,keySimples:string|undefined)=>{
    const key=keyDuplo??keySimples??''
    if(!Object.hasOwn(tags,key)){desconhecida=true;return ''}
    return tags[key]
  }).trim()
  if(desconhecida||TEXTO_TAG_INCONHECIDA.test(texto)||!texto||texto.length>4096)
    return {status:'bloqueado',codigo:'MODELO_TAG_INVALIDA'}
  if(c.eventoCodigo==='REMARCACAO_SOLICITADA_WHATSAPP' &&
    /https?:\/\//i.test(texto))
    return {status:'bloqueado',codigo:'LINK_AUTOATENDIMENTO_INDISPONIVEL'}
  return {status:'pronto',corpo:{
    messaging_product:'whatsapp',recipient_type:'individual',
    to:c.destinatarioE164.slice(1),
    type:'text',context:{message_id:c.mensagemCliqueId},
    text:{body:texto,preview_url:false}
  }}
}

// HML: convite administrativo e ciclo autenticado de confirmações.
import { criarHandler } from './handler.ts'
Deno.serve(criarHandler(Deno.env))

import {prevalidarMetaHml} from './prevalidarMetaHml.ts'
import {orquestrarConviteHml} from './orquestradorConviteHml.ts'
import {NOME_TEMPLATE_HML} from './solicitacaoTemplateMeta.ts'
import {criarTransporteMetaHml,envioMetaHmlHabilitado as envioMetaPermitido} from '../mensageria-outbox-hml/transporteMetaHml.ts'
import {criarAdaptadorRpcOutboxHml} from '../mensageria-outbox-hml/adaptadorRpcOutboxHml.ts'
import {executarUmAgradecimentoHml} from '../mensageria-outbox-hml/orquestradorDespachoHml.ts'

export const REF = 'jgtctzqieyorhvqxjbpk'
const BASE = 'https://' + REF + '.supabase.co'
const ORIGENS = new Set(['http://127.0.0.1:5173','http://localhost:5173'])
type Env = { get(nome:string):string|undefined }
type Fetch = typeof fetch
type Config = {key:string; adminId:string}
const uuid = /^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/i

function resposta(status:number,data:Record<string,unknown>,origin:string|null) {
  return Response.json(data,{status,headers:{
    'access-control-allow-origin': origin && ORIGENS.has(origin) ? origin : 'null',
    'access-control-allow-headers':'authorization,apikey,content-type,x-client-info',
    'access-control-allow-methods':'POST,OPTIONS',
    'cache-control':'no-store','vary':'Origin'
  }})
}
function config(env:Env):Config|null {
  if (env.get('SUPABASE_URL')!==BASE || env.get('HML_PROJECT_REF')!==REF) return null
  const key=env.get('SUPABASE_SERVICE_ROLE_KEY')??''
  const adminId=env.get('HML_OPERATOR_UUID')??''
  if (!key || !uuid.test(adminId)) return null
  return {key,adminId}
}

async function backend(c:Config,endpoint:string,credencial:string,method:'GET'|'POST',
  fetchImpl:Fetch, body?:Record<string,unknown>) {
  const res=await fetchImpl(BASE+endpoint,{
    method,redirect:'error',signal:AbortSignal.timeout(12000),
    headers:{apikey:c.key,authorization:'Bearer '+credencial,'content-type':'application/json'},
    ...(method==='POST'?{body:JSON.stringify(body)}:{})
  })
  return {ok:res.ok,data:await res.json().catch(()=>null)}
}
async function operadorAutorizado(req:Request,c:Config,fetchImpl:Fetch) {
  const auth=req.headers.get('authorization')??''
  if (!/^Bearer [A-Za-z0-9_.-]{20,8192}$/.test(auth)) return false
  const jwt=auth.slice(7)
  const user=await backend(c,'/auth/v1/user',jwt,'GET',fetchImpl)
  if (!user.ok || user.data?.id!==c.adminId ||
      user.data?.app_metadata?.role!=='internal' ||
      user.data?.app_metadata?.whatsapp_admin!==true) return false
  const valid=await backend(c,'/rest/v1/rpc/mensageria_hml_autorizar_operador',
    jwt,'POST',fetchImpl,{p_expected:c.adminId})
  return valid.ok && valid.data===true
}

export function criarHandler(env:Env,fetchImpl:Fetch=fetch) {
  return async function(req:Request):Promise<Response> {
    const origem=req.headers.get('origin')
    if(origem && !ORIGENS.has(origem))return resposta(403,{codigo:'ORIGEM_NEGADA'},origem)
    if(req.method==='OPTIONS')return new Response(null,{status:204,headers:{
      'access-control-allow-origin':origem && ORIGENS.has(origem)?origem:'null',
      'access-control-allow-headers':'authorization,apikey,content-type,x-client-info',
      'access-control-allow-methods':'POST,OPTIONS','vary':'Origin'
    }})
    if(req.method!=='POST' || !new URL(req.url).pathname.endsWith('/mensageria-confirmacao-hml'))
      return resposta(405,{codigo:'METODO_NEGADO'},origem)
    if(Number(req.headers.get('content-length')??0)>4096)
      return resposta(413,{codigo:'CORPO_GRANDE'},origem)
    const c=config(env)
    if(!c)return resposta(503,{codigo:'HML_NAO_CONFIGURADA'},origem)
    let autorizado=false
    try{autorizado=await operadorAutorizado(req,c,fetchImpl)}catch{/* não expor credenciais */}
    if(!autorizado)return resposta(403,{codigo:'OPERADOR_NAO_AUTORIZADO'},origem)
    let body:Record<string,unknown>
    try {
      const text=await req.text()
      if(text.length>4096)throw Error('grande')
      const json:unknown=JSON.parse(text)
      if(!json||typeof json!=='object'||Array.isArray(json))throw Error('invalido')
      body=json as Record<string,unknown>
    } catch{return resposta(400,{codigo:'CORPO_INVALIDO'},origem)}

    if(body.acao==='prevalidar_meta'){
      if(Object.keys(body).length!==1)return resposta(400,{codigo:'CORPO_INVALIDO'},origem)
      return resposta(200,await prevalidarMetaHml(env,fetchImpl),origem)
    }

    // O ciclo usa a mesma autenticação administrativa das demais ações.
    const ciclo=body.acao==='processar_ciclo'

    const destinoPermitido=env.get('HML_TEST_RECIPIENT_E164')??''
    const rpc=async (nome:string,params:Record<string,unknown>)=>{
      const r=await backend(c,'/rest/v1/rpc/mensageria_hml_'+nome,c.key,'POST',fetchImpl,{
        ...params,p_operador:c.adminId
      })
      if(!r.ok||!r.data||typeof r.data!=='object'||Array.isArray(r.data))throw Error('RPC_INDISPONIVEL')
      return r.data
    }
    async function operacao(acao='status',segundos:number|null=null){
      return rpc('operacao',{p_acao:acao,p_segundos:segundos})
    }
    if(body.acao==='operacao'){
      const comando=body.comando
      if(typeof comando!=='string'||!['status','ligar_receptor','desligar_receptor','ligar_processamento',
        'desligar_processamento','abrir_envio','fechar_envio','emergencia'].includes(comando)||
        Object.keys(body).some(chave=>!['acao','comando','segundos'].includes(chave))||
        (comando==='abrir_envio'? !Number.isInteger(body.segundos)||Number(body.segundos)<1||Number(body.segundos)>180
          :body.segundos!==undefined))
        return resposta(400,{codigo:'COMANDO_INVALIDO'},origem)
      if(comando==='abrir_envio'){
        if(env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')
          return resposta(503,{codigo:'ENVIO_DESATIVADO'},origem)
        const meta=await prevalidarMetaHml(env,fetchImpl)
        if(!meta.credencial_aceita||!meta.telefone_acessivel||!meta.telefone_na_waba||
          meta.aplicativo_hml!==true||meta.permissao_envio!==true)
          return resposta(409,{codigo:'META_NAO_VALIDADA'},origem)
      }
      try{
        const r=await operacao(comando,comando==='abrir_envio'?Number(body.segundos):null)
        if(r.status!=='ok')return resposta(409,{codigo:r.status==='janela_ja_ativa'?'JANELA_JA_ATIVA':'OPERACAO_RECUSADA'},origem)
        return resposta(200,{receptor:r.receptor===true&&env.get('HML_RECEPTOR_BLOQUEIO_EMERGENCIAL')!=='true',
          processamento:r.processamento===true,
          envio_expira_em:env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true'?null:r.envio_expira_em,
          revisao:r.revisao,atualizado_em:r.atualizado_em},origem)
      }catch{return resposta(503,{codigo:'CONTROLES_INDISPONIVEIS'},origem)}
    }
    if(body.acao==='evidencia_operacao'){
      if(Object.keys(body).length!==1)return resposta(400,{codigo:'CORPO_INVALIDO'},origem)
      try{
        const dados=await rpc('evidencia_operacao',{})
        return resposta(dados.status==='ok'?200:503,dados,origem)
      }catch{return resposta(503,{codigo:'EVIDENCIA_INDISPONIVEL'},origem)}
    }

    if(body.acao==='listar_atendimentos'){
      try{
        const r=await rpc('contexto_convite',{p_atendimento:null,p_preparo:null})
        if(r.status!=='ok'||!Array.isArray(r.itens))throw Error('AGENDA_INDISPONIVEL')
        return resposta(200,{itens:r.itens},origem)
      }catch{return resposta(503,{codigo:'AGENDA_INDISPONIVEL'},origem)}
    }
    let controles:Record<string,unknown>|null=null
    if(['enviar_convite','processar_lote','processar_ciclo','processar_item','despachar_agradecimento'].includes(String(body.acao))){
      try{controles=await operacao()}catch{return resposta(503,{codigo:'CONTROLES_INDISPONIVEIS'},origem)}
      if(controles.status!=='ok')return resposta(503,{codigo:'CONTROLES_INDISPONIVEIS'},origem)
    }
    const expira=typeof controles?.envio_expira_em==='string'?controles.envio_expira_em:null
    const ambiente={get(nome:string){
      if(nome==='HML_OUTBOX_SEND_EXPIRES_AT')return expira??undefined
      if(['HML_CONFIRMATION_REAL_SEND_ENABLED','HML_OUTBOX_SEND_ENABLED','HML_OUTBOX_RPC_ENABLED'].includes(nome))
        return expira&&env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')!=='true'?'true':'false'
      return env.get(nome)
    }}
    const enviar=criarTransporteMetaHml({ambiente,requisitar:async (url,init)=>{
      const atual=await operacao()
      if(atual.status!=='ok'||atual.revisao!==controles?.revisao||atual.envio_expira_em!==expira||
        !expira||Date.parse(expira)<=Date.now()||env.get('HML_ENVIO_BLOQUEIO_EMERGENCIAL')==='true')
        throw Error('AUTORIZACAO_ENCERRADA')
      return fetchImpl(url,init)
    }})
    async function despachar(){
      if(!envioMetaPermitido(ambiente))return null
      const ops=criarAdaptadorRpcOutboxHml({ambiente,requisitar:fetchImpl,enviar})
      return ops.configurado()?executarUmAgradecimentoHml({
        projeto:REF,operadorId:c!.adminId,permitidoE164:destinoPermitido,envioHabilitado:true,
        autorizacaoExpiraIso:expira,agora:()=>new Date(),chaveAleatoria:()=>crypto.randomUUID()
      },ops):null
    }
    if(body.acao==='despachar_agradecimento'){
      if(Object.keys(body).length!==1)return resposta(400,{codigo:'CORPO_INVALIDO'},origem)
      try{
        const r=await despachar()
        return r?resposta(200,{despacho:r},origem):resposta(503,{codigo:'ENVIO_DESATIVADO'},origem)
      }catch{return resposta(503,{codigo:'DESPACHO_INDISPONIVEL'},origem)}
    }
    if(body.acao==='enviar_convite'){
      const envio=envioMetaPermitido(ambiente)
      if(!envio||env.get('HML_CONFIRMATION_APPROVED_TEMPLATE')!==NOME_TEMPLATE_HML)
        return resposta(503,{codigo:'ENVIO_OU_TEMPLATE_NAO_AUTORIZADO'},origem)
      if(typeof body.atendimentoId!=='string'||!uuid.test(body.atendimentoId)||
          Object.keys(body).length!==2)
        return resposta(400,{codigo:'ATENDIMENTO_INVALIDO'},origem)
      const atendimentoId=body.atendimentoId
      try{
        const contexto=async (preparo:string|null)=>rpc('contexto_convite',{
          p_atendimento:atendimentoId,p_preparo:preparo
        })
        const dados=await contexto(null)
        if(dados.status!=='ok'||typeof dados.destino!=='string'||
            !Array.isArray(dados.parametros)||dados.parametros.length!==4||
            !dados.parametros.every((p:unknown)=>typeof p==='string'))
          return resposta(409,{codigo:'ATENDIMENTO_NAO_ELEGIVEL'},origem)
        const resultado=await orquestrarConviteHml({
          projectRef:REF,envioHabilitado:true,expiraEm:expira,
          destinatarioPermitidoE164:destinoPermitido,relogio:()=>new Date()
        },{
          atendimentoId,destinoE164:dados.destino,parametros:dados.parametros,
          templateAprovadoNome:NOME_TEMPLATE_HML
        },{
          preparar:p=>rpc('preparar_convite',{p_atendimento:p.atendimentoId,p_preparo:p.preparoId,
            p_hash_confirmar:p.hashConfirmar,p_hash_remarcar:p.hashRemarcar}),
          async validarPreparo(preparoId){
            const atual=await contexto(preparoId)
            return atual.status==='ok'&&atual.destino===dados.destino&&
              JSON.stringify(atual.parametros)===JSON.stringify(dados.parametros)
          },
          async enviar(corpo){
            const r=await enviar(corpo)
            return {httpStatus:r.httpStatus,messageId:r.wamid}
          },
          vincular:p=>rpc('vincular_convite_aceito',{p_preparo:p.preparoId,p_meta_message_id:p.messageId}),
          abandonar:p=>rpc('abandonar_preparo',{p_preparo:p.preparoId})
        })
        return resposta(resultado.estado==='vinculado'?200:409,resultado,origem)
      }catch{return resposta(503,{codigo:'CONVITE_INDISPONIVEL'},origem)}
    }

    if(body.acao==='diagnostico') {
      try {
        const r=await backend(c,'/rest/v1/rpc/mensageria_hml_diagnostico_confirmacoes',
          c.key,'POST',fetchImpl,{p_operador:c.adminId})
        if(!r.ok || r.data?.status!=='ok')return resposta(503,{codigo:'DIAGNOSTICO_INDISPONIVEL'},origem)
        const campos=[
          'convites_ativos','convites_confirmados','convites_expirados',
          'cliques_processados','remarcacoes_pendentes','respostas_aguardando',
          'respostas_prontas','respostas_reservadas','respostas_aceitas_meta',
          'respostas_recusadas_meta','respostas_indeterminadas',
          'templates_meta_cadastrados','agendamentos_hml',
        ] as const
        const resultado:Record<string,unknown>={}
        for(const campo of campos) {
          const valor=r.data[campo]
          if(typeof valor!=='number'||!Number.isSafeInteger(valor)||valor<0)
            return resposta(503,{codigo:'DIAGNOSTICO_INVALIDO'},origem)
          resultado[campo]=valor
        }
        return resposta(200,{
          ...resultado,ambiente:'homologacao',processamento_habilitado:
            (await operacao()).processamento===true,
          envio_automatico_habilitado:false,
        },origem)
      }catch{return resposta(503,{codigo:'DIAGNOSTICO_INDISPONIVEL'},origem)}
    }
    if(body.acao==='processar_lote'||ciclo) {
      // Execução separada do consumidor antigo. Desativada até autorização e E2E.
      if(controles?.processamento!==true)
        return resposta(503,{codigo:'PROCESSAMENTO_DESATIVADO'},origem)
      const limite=body.limite===undefined?(ciclo?1:5):body.limite
      if(typeof limite!=='number'||!Number.isInteger(limite)||limite<1||limite>10)
        return resposta(400,{codigo:'LIMITE_INVALIDO'},origem)
      try{
        const lista=await backend(c,'/rest/v1/rpc/mensageria_hml_listar_cliques_pendentes',
          c.key,'POST',fetchImpl,{p_operador:c.adminId,p_limite:limite})
        if(!lista.ok||lista.data?.status!=='ok'||!Array.isArray(lista.data?.itens)||
            lista.data.itens.length>limite||
            !lista.data.itens.every((id:unknown)=>typeof id==='string'&&uuid.test(id)))
          return resposta(503,{codigo:'FILA_INDISPONIVEL'},origem)
        const contagem:Record<string,number>={}
        let erros=0
        for(const itemId of lista.data.itens as string[]){
          try{
            const resultado=await backend(c,'/rest/v1/rpc/mensageria_hml_processar_clique_operacao',
              c.key,'POST',fetchImpl,{p_item:itemId,p_operador:c.adminId})
            if(!resultado.ok||typeof resultado.data?.status!=='string'){
              erros++;continue
            }
            const status=resultado.data.status as string
            if(!new Set(['confirmado','remarcacao_pendente','ja_processado',
              'ignorado','rejeitado','expirado','conflito','ja_resolvido','desativado']).has(status)){
              erros++;continue
            }
            contagem[status]=(contagem[status]??0)+1
          }catch{erros++}
        }
        // A RPC de clique já terminou a transação antes de consultar a outbox.
        const despacho=ciclo?await despachar():null
        return resposta(erros>0?503:200,{
          codigo:erros>0?'LOTE_PARCIAL':'LOTE_CONCLUIDO',
          ...(ciclo?{despacho}:{}),
          encontrados:lista.data.itens.length,erros,contagem,
          envio_automatico_habilitado:despacho!==null
        },origem)
      }catch{return resposta(503,{codigo:'FILA_INDISPONIVEL'},origem)}
    }
    if(body.acao==='processar_item') {
      if(controles?.processamento!==true)
        return resposta(503,{codigo:'PROCESSAMENTO_DESATIVADO'},origem)
      if(typeof body.itemId!=='string'||!uuid.test(body.itemId))
        return resposta(400,{codigo:'ITEM_INVALIDO'},origem)
      try {
        const r=await backend(c,'/rest/v1/rpc/mensageria_hml_processar_clique_operacao',
          c.key,'POST',fetchImpl,{p_item:body.itemId,p_operador:c.adminId})
        if(!r.ok || typeof r.data?.status!=='string')return resposta(503,{codigo:'PROCESSAMENTO_INDETERMINADO'},origem)
        const statuses=new Set(['confirmado','remarcacao_pendente','ja_processado',
          'ignorado','rejeitado','expirado','conflito','ja_resolvido','desativado'])
        if(!statuses.has(r.data.status))return resposta(503,{codigo:'RESULTADO_INVALIDO'},origem)
        return resposta(200,{status:r.data.status,codigo:typeof r.data.codigo==='string'?r.data.codigo:null},origem)
      }catch{return resposta(503,{codigo:'PROCESSAMENTO_INDETERMINADO'},origem)}
    }
    return resposta(400,{codigo:'ACAO_INVALIDA'},origem)
  }
}

import {ESCOPO_META_HML} from './escopoMetaHml.ts'

type Env = {get(name:string):string|undefined}
type Objeto = Record<string,unknown>
const {projeto,wabaId,phoneNumberId,appId,versaoGraph}=ESCOPO_META_HML
const base='https://graph.facebook.com/'+versaoGraph

function objeto(valor:unknown):Objeto|null{
  return valor!==null&&typeof valor==='object'&&!Array.isArray(valor)?valor as Objeto:null
}

export async function prevalidarMetaHml(env:Env,requisitar:typeof fetch){
  const token=env.get('HML_META_TEST_ACCESS_TOKEN')??''
  const configurada=env.get('HML_PROJECT_REF')===projeto&&
    env.get('SUPABASE_URL')==='https://'+projeto+'.supabase.co'&&
    /^[A-Za-z0-9_.|~-]{32,4096}$/.test(token)
  async function ler(path:string){
    if(!configurada)return null
    try{
      const r=await requisitar(base+path,{
        method:'GET',redirect:'error',signal:AbortSignal.timeout(8000),
        headers:{authorization:'Bearer '+token,accept:'application/json'}
      })
      return r.ok?objeto(await r.json()):null
    }catch{return null}
  }
  const [telefone,lista,permissoes,app]=await Promise.all([
    ler('/'+phoneNumberId+'?fields=id'),
    ler('/'+wabaId+'/phone_numbers?fields=id&limit=100'),
    ler('/me/permissions?limit=100'),
    ler('/app?fields=id')
  ])
  const acessoTelefone=telefone?.id===phoneNumberId
  const vinculoWaba=Array.isArray(lista?.data)&&lista.data.some(item=>objeto(item)?.id===phoneNumberId)
  function permissao(nome:string){
    if(!Array.isArray(permissoes?.data))return null
    const item=permissoes.data.map(objeto).find(p=>p?.permission===nome)
    return item?item.status==='granted':objeto(permissoes.paging)?.next?null:false
  }
  return {
    credencial_configurada:configurada,
    credencial_aceita:acessoTelefone||vinculoWaba,
    telefone_acessivel:acessoTelefone,
    telefone_na_waba:vinculoWaba,
    aplicativo_hml:typeof app?.id==='string'?app.id===appId:null,
    permissao_gestao:permissao('whatsapp_business_management'),
    permissao_envio:permissao('whatsapp_business_messaging')
  }
}

/**
 * Orquestrador backend — convite com dois botões.
 * Dependências são injetadas para permitir testes SEM chamadas à Meta.
 *
 * AVISO: este módulo não está conectado à Edge Function pública.
 * Antes de ligar o transporte, exigir confirmação de template APPROVED
 * na Meta, fonte autoritativa dos dados e autorização de envio de curta duração.
 */
import {wamidValidoHml} from './validarWamidHml.ts'
import {prepararTemplateConfirmacaoHml,type CorpoTemplateMeta} from './templateConfirmacao.ts'
import {NOME_TEMPLATE_HML} from './solicitacaoTemplateMeta.ts'
const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
export type RegistroPreparo={
  status:'preparado'|'ja_preparado'|'conflito'|'rejeitado'
  convite_id?:string
}
export type RespostaTransporte={httpStatus:number;messageId?:string|null}
export type OperacoesConvite={
  preparar(input:{
    atendimentoId:string;preparoId:string;hashConfirmar:string;hashRemarcar:string
  }):Promise<RegistroPreparo>
  validarPreparo?(preparoId:string):Promise<boolean>
  enviar(corpo:CorpoTemplateMeta):Promise<RespostaTransporte>
  vincular(input:{preparoId:string;messageId:string}):Promise<{status:string}>
  abandonar(input:{preparoId:string}):Promise<{status:string}>
}
export type ContextoConvite={
  // Deverá ser produzido por consulta SQL no backend, nunca enviado pelo browser.
  atendimentoId:string
  destinoE164:string
  parametros:readonly string[]
  templateAprovadoNome:string
}
export type AutorizacaoHml={
  projectRef:string
  envioHabilitado:boolean
  expiraEm:string|null
  destinatarioPermitidoE164:string
  relogio:()=>Date
}
export type EstadoEnvioConvite=
 'bloqueado'|'preparo_rejeitado'|'preparo_repetido'|'meta_rejeitada'|
 'resultado_indeterminado'|'aceito_sem_vinculo'|'vinculado'

export async function orquestrarConviteHml(
  auth:AutorizacaoHml,ctx:ContextoConvite,ops:OperacoesConvite,
):Promise<{estado:EstadoEnvioConvite;codigo:string}> {
  const resto=auth.expiraEm?Date.parse(auth.expiraEm)-auth.relogio().getTime():NaN
  if(auth.projectRef!==REF || auth.envioHabilitado!==true ||
     !Number.isFinite(resto)||resto<=0||resto>180_000) {
    return {estado:'bloqueado',codigo:'SEM_JANELA_DE_TESTE'}
  }
  if(!UUID.test(ctx.atendimentoId) ||
     ctx.templateAprovadoNome!==NOME_TEMPLATE_HML){
    return {estado:'bloqueado',codigo:'CONTEXTO_OU_TEMPLATE_NAO_APROVADO'}
  }
  // Testa o número exato antes de qualquer transação ou HTTP.
  let template:Awaited<ReturnType<typeof prepararTemplateConfirmacaoHml>>
  try{
    template=await prepararTemplateConfirmacaoHml({
      destinoE164:ctx.destinoE164,
      permitidoE164:auth.destinatarioPermitidoE164,
      templateNome:ctx.templateAprovadoNome,
      idioma:'pt_BR',
      parametros:ctx.parametros
    })
  }catch{
    return {estado:'bloqueado',codigo:'DESTINO_OU_TEMPLATE_INVALIDO'}
  }
  const preparoId=crypto.randomUUID()
  let preparo:RegistroPreparo
  try{
    preparo=await ops.preparar({
      atendimentoId:ctx.atendimentoId,
      preparoId,
      hashConfirmar:template.hashConfirmar,
      hashRemarcar:template.hashRemarcar
    })
  }catch{
    return {estado:'preparo_rejeitado',codigo:'RESERVA_INDISPONIVEL'}
  }
  if(preparo.status==='ja_preparado')
    return {estado:'preparo_repetido',codigo:'NAO_REENVIAR_PREPARO_EXISTENTE'}
  if(preparo.status!=='preparado'||!preparo.convite_id||!UUID.test(preparo.convite_id))
    return {estado:'preparo_rejeitado',codigo:'PREPARO_NAO_CONFIRMADO'}

  if(ops.validarPreparo&&!await ops.validarPreparo(preparoId).catch(()=>false)){
    await ops.abandonar({preparoId}).catch(()=>null)
    return {estado:'preparo_rejeitado',codigo:'AGENDAMENTO_ALTERADO_ANTES_DO_ENVIO'}
  }

  // Depois de uma chamada à Meta, resposta perdida significa envio INDETERMINADO.
  // Nunca repetir automaticamente neste cenário — um segundo POST duplicaria
  // o convite e os segredos gerados na chamada anterior seriam perdidos.
  // Segunda verificação imediatamente antes de cada POST externo.
  // Se a reserva demorou, não basta a autorização válida no início da operação.
  const restanteAntesDoPost=auth.expiraEm
    ? Date.parse(auth.expiraEm)-auth.relogio().getTime():NaN
  if(!Number.isFinite(restanteAntesDoPost) ||
      restanteAntesDoPost<=0 || restanteAntesDoPost>180_000){
    await ops.abandonar({preparoId}).catch(()=>null)
    return {estado:'bloqueado',codigo:'JANELA_DE_TESTE_ENCERROU_ANTES_DO_ENVIO'}
  }
  let meta:RespostaTransporte
  try{
    meta=await ops.enviar(template.corpoApi)
  }catch{
    return {estado:'resultado_indeterminado',codigo:'META_RESPOSTA_INCERTA_NAO_REENVIAR'}
  }
  if(meta.httpStatus>=400&&meta.httpStatus<500){
    // Resposta explícita de recusa do servidor: tente encerrar preparo.
    await ops.abandonar({preparoId}).catch(()=>null)
    return {estado:'meta_rejeitada',codigo:'META_REJEITOU_TEMPLATE'}
  }
  if(meta.httpStatus<200||meta.httpStatus>=300||!meta.messageId||
     !wamidValidoHml(meta.messageId)){
    return {estado:'resultado_indeterminado',codigo:'META_ACEITE_NAO_CONFIRMADO'}
  }
  // Aceite Meta NÃO significa agendamento confirmado. Apenas vincula convite.
  try{
    const vinculo=await ops.vincular({preparoId,messageId:meta.messageId})
    if(vinculo.status==='vinculado'||vinculo.status==='ja_vinculado')
      return {estado:'vinculado',codigo:'CONVITE_PRONTO_PARA_CLIQUE'}
    return {estado:'aceito_sem_vinculo',codigo:'META_ACEITOU_MAS_VINCULO_PENDENTE'}
  }catch{
    return {estado:'aceito_sem_vinculo',codigo:'META_ACEITOU_MAS_BANCO_INDISPONIVEL'}
  }
}

// Preserva o ID opaco da Meta, inclusive o padding Base64 no fim.
export function wamidValidoHml(valor:unknown):valor is string{
  return typeof valor==='string'&&valor.length>=10&&valor.length<=300&&
    /^wamid\.[A-Za-z0-9+/_.-]{4,}={0,2}$/.test(valor)&&!/[\r\n]/.test(valor)
}

/**
 * Montagem PURA de template utilitário com 2 quick replies da Meta.
 * Exclusivamente para utilização no backend. Este módulo:
 * - não lê chaves da Meta nem faz HTTP;
 * - não envia mensagem e não cadastra convite;
 * - gera tokens criptograficamente aleatórios, que só devem ser usados
 *   na chamada Cloud API e armazenados no banco em hash SHA-256.
 *
 * Importante: os botões "Confirmar" e "Remarcar" e os parâmetros de body
 * devem coincidir com o TEMPLATE APROVADO pela Meta.
 */
export type TemplateConfirmacaoEntrada = {
  destinoE164: string
  permitidoE164: string
  templateNome: string
  idioma: 'pt_BR'
  parametros: readonly string[]
}
export type CorpoTemplateMeta = {
  messaging_product: 'whatsapp'
  to: string
  type: 'template'
  template: {
    name: string
    language:{code:'pt_BR'}
    components: Array<
      {type:'body'; parameters:Array<{type:'text';text:string}>} |
      {type:'button';sub_type:'quick_reply';index:'0'|'1';
       parameters:[{type:'payload';payload:string}]}
    >
  }
}
export type ConvitePreparadoBackend = {
  corpoApi: CorpoTemplateMeta
  segredoConfirmar: string
  segredoRemarcar: string
  hashConfirmar: string
  hashRemarcar: string
}
const TEL = /^\+55[1-9][0-9][2-9][0-9]{7,8}$/
const NOME = /^[a-z][a-z0-9_]{2,100}$/
function numeroNormalizado(valor:string){return valor.replace(/^\+/,'')}
async function sha256(s:string){
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))
  return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')
}
export async function prepararTemplateConfirmacaoHml(
  dados:TemplateConfirmacaoEntrada,
):Promise<ConvitePreparadoBackend> {
  if(!TEL.test(dados.destinoE164) ||
     numeroNormalizado(dados.destinoE164)!==numeroNormalizado(dados.permitidoE164))
    throw Error('DESTINATARIO_NAO_AUTORIZADO')
  if(!NOME.test(dados.templateNome)||dados.idioma!=='pt_BR')throw Error('TEMPLATE_INVALIDO')
  if(dados.parametros.length>8 || dados.parametros.some(p=>typeof p!=='string'||!p.trim()||p.length>255))
    throw Error('PARAMETROS_INVALIDOS')
  const segredoConfirmar='KPAG1_'+crypto.randomUUID()
  const segredoRemarcar='KPAG1_'+crypto.randomUUID()
  if(segredoConfirmar===segredoRemarcar)throw Error('ENTROPIA_INSUFICIENTE')
  const hashConfirmar=await sha256(segredoConfirmar)
  const hashRemarcar=await sha256(segredoRemarcar)
  const components:CorpoTemplateMeta['template']['components']=[]
  if(dados.parametros.length)components.push({
    type:'body',parameters:dados.parametros.map(text=>({type:'text',text}))
  })
  components.push({
    type:'button',sub_type:'quick_reply',index:'0',
    parameters:[{type:'payload',payload:segredoConfirmar}]
  },{
    type:'button',sub_type:'quick_reply',index:'1',
    parameters:[{type:'payload',payload:segredoRemarcar}]
  })
  return {
    corpoApi:{messaging_product:'whatsapp',to:numeroNormalizado(dados.destinoE164),
      type:'template',template:{name:dados.templateNome,language:{code:'pt_BR'},components}},
    segredoConfirmar,segredoRemarcar,hashConfirmar,hashRemarcar
  }
}

