/**
 * Transporte para um único agradecimento HML WhatsApp Cloud API.
 *
 * É um adaptador isolado para testes com fetch injetado:
 * NÃO é importado pela Edge mensageria-outbox-hml v1.
 * NÃO registra corpo, token, telefone, headers ou resposta bruta em logs.
 * SEM retry automático. A decisão de reservar/finalizar pertence à outbox.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {NOME_TEMPLATE_HML} from '../mensageria-confirmacao-hml/solicitacaoTemplateMeta.ts'
import type {CorpoTemplateMeta} from '../mensageria-confirmacao-hml/templateConfirmacao.ts'
import type {EnvioTextoMeta} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

import { ESCOPO_META_HML } from '../mensageria-confirmacao-hml/escopoMetaHml.ts'

const HML=ESCOPO_META_HML.projeto
const HML_URL='https://'+HML+'.supabase.co'
const META_PHONE_HML=ESCOPO_META_HML.phoneNumberId
const GRAPH='https://graph.facebook.com/'+ESCOPO_META_HML.versaoGraph+'/'+META_PHONE_HML+'/messages'
const DESTINO=/^55[1-9][0-9]{9,10}$/

export type AmbienteMetaHml={get:(name:string)=>string|undefined}
export type ResultadoMetaHml={httpStatus:number;wamid:string|null}
export type OpcoesTransporteHml={
  ambiente:AmbienteMetaHml
  requisitar?:(url:string,init:RequestInit)=>Promise<Response>
  agora?:()=>number
}

function permitido(env:AmbienteMetaHml,agora:number):{destino:string;token:string}|null{
  if(env.get('HML_PROJECT_REF')!==HML||
     env.get('SUPABASE_URL')!==HML_URL||
     env.get('HML_CONFIRMATION_REAL_SEND_ENABLED')!=='true'||
     env.get('HML_META_TEST_WABA_ID')!==ESCOPO_META_HML.wabaId||
     env.get('HML_META_TEST_APP_ID')!==ESCOPO_META_HML.appId||
     env.get('HML_META_TEST_PHONE_NUMBER_ID')!==META_PHONE_HML||
     env.get('HML_OUTBOX_SEND_ENABLED')!=='true')return null
  const fim=Date.parse(env.get('HML_OUTBOX_SEND_EXPIRES_AT')??'')
  if(!Number.isFinite(agora)||!Number.isFinite(fim)||
     fim<=agora||fim-agora>180_000)return null
  const destino=env.get('HML_TEST_RECIPIENT_E164')??''
  const token=env.get('HML_META_TEST_ACCESS_TOKEN')??''
  if(!DESTINO.test(destino)||token.length<32||token.length>4096||
     /[\r\n]/.test(token))return null
  return {destino,token}
}
export function envioMetaHmlHabilitado(env:AmbienteMetaHml):boolean{
  return permitido(env,Date.now())!==null
}
function corpoValido(c:EnvioTextoMeta,destino:string):boolean {
  return c?.messaging_product==='whatsapp'&&
    c.recipient_type==='individual'&&
    c.to===destino&&c.type==='text'&&
    c.text?.preview_url===false&&
    typeof c.text?.body==='string'&&
    c.text.body.trim().length>=1&&c.text.body.length<=4096&&
    typeof c.context?.message_id==='string'&&
    wamidValidoHml(c.context.message_id)
}

export function criarTransporteMetaHml({ambiente,requisitar=fetch,agora=Date.now}:OpcoesTransporteHml){
  return async (body:EnvioTextoMeta|CorpoTemplateMeta):Promise<ResultadoMetaHml>=>{
    const cfg=permitido(ambiente,agora())
    if(!cfg)throw new Error('ENVIO_META_HML_NAO_AUTORIZADO')
    if(body?.type==='template'
      ? body.to!==cfg.destino||body.messaging_product!=='whatsapp'||
        body.template.name!==NOME_TEMPLATE_HML||body.template.language.code!=='pt_BR'
      : !corpoValido(body,cfg.destino))throw new Error('MENSAGEM_META_HML_INVALIDA')
    // Confere a janela uma segunda vez imediatamente antes do POST.
    const atual=permitido(ambiente,agora())
    if(!atual||atual.destino!==cfg.destino||atual.token!==cfg.token)
      throw new Error('AUTORIZACAO_EXPIRADA')
    let res:Response
    try{
      res=await requisitar(GRAPH,{
        method:'POST',redirect:'error',signal:AbortSignal.timeout(12000),
        headers:{authorization:'Bearer '+cfg.token,'content-type':'application/json'},
        body:JSON.stringify(body)
      })
    }catch{
      // A Meta pode ter aceitado antes de ocorrer timeout, queda de rede
      // ou redirecionamento. É proibido repetir automaticamente a chamada.
      throw new Error('META_RESPOSTA_INDETERMINADA')
    }
    if(!Number.isInteger(res.status)||res.status<200||res.status>599)
      return {httpStatus:503,wamid:null}
    if(res.status<200||res.status>=300)return {httpStatus:res.status,wamid:null}
    let parsed:unknown
    try{parsed=await res.json()}catch{
      return {httpStatus:res.status,wamid:null}
    }
    if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))
      return {httpStatus:res.status,wamid:null}
    const response=parsed as {
      messaging_product?:unknown
      contacts?:{input?:unknown;wa_id?:unknown}[]
      messages?:{id?:unknown}[]
    }
    const id=response.messages?.[0]?.id
    // contacts[].wa_id pode ser diferente da entrada (nono dígito BR).
    // contacts[].input, quando presente, precisa refletir o destino pedido.
    if(response.messaging_product!=='whatsapp'||
       (Array.isArray(response.contacts)&&
         (response.contacts[0]?.input!==cfg.destino))||
       !Array.isArray(response.messages)||
       typeof id!=='string'||!wamidValidoHml(id))
      return {httpStatus:res.status,wamid:null}
    return {httpStatus:res.status,wamid:id}
  }
}

/**
 * KAZA PET • adapter RPC da outbox de agradecimentos HML.
 *
 * APENAS para execução injetada/testes. NÃO importado na Edge publicada.
 * Sem chamadas de Graph API, sem agendamento, sem acesso do navegador.
 * Nenhum método acessa a rede quando HML_OUTBOX_RPC_ENABLED !== 'true'.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import type {OperacoesDespachoHml} from './orquestradorDespachoHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const BASE='https://'+REF+'.supabase.co'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const E164=/^\+55[1-9][0-9]{9,10}$/
const ESTADOS_RESERVA=new Set([
 'reservado','ja_reservado','nao_pronto','agenda_invalida',
 'janela_inbound_indisponivel','outro'
])
const ESTADOS_FINAL=new Set(['aceito_meta','recusado_meta','indeterminado'])
const CODIGO=/^[A-Z][A-Z0-9_]{1,63}$/
const RPCS={
  listar:'mensageria_hml_outbox_listar_pendentes',
  reservar:'mensageria_hml_outbox_reservar',
  contexto:'mensageria_hml_outbox_contexto',
  finalizar:'mensageria_hml_outbox_finalizar'
} as const
type Env={get:(nome:string)=>string|undefined}
type Fetch=(url:string,init:RequestInit)=>Promise<Response>
type Envio=OperacoesDespachoHml['enviar']

export type ConfigAdaptadorRpcHml={
  ambiente:Env
  requisitar:Fetch // obrigatório: teste sempre injetado, sem fallback implícito
  enviar:Envio // transporte injetado; não importamos Meta aqui
}
export type RpcOutboxHml=OperacoesDespachoHml & {
  /** Retorna apenas se o ambiente indica HML e a flag de RPC está ligada */
  configurado:()=>boolean
}
export function criarAdaptadorRpcOutboxHml({
  ambiente,requisitar,enviar
}:ConfigAdaptadorRpcHml):RpcOutboxHml{
  const permitido=()=>{
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')??''
    const operator=ambiente.get('HML_OPERATOR_UUID')??''
    return ambiente.get('SUPABASE_URL')===BASE&&
      ambiente.get('HML_PROJECT_REF')===REF&&
      ambiente.get('HML_OUTBOX_RPC_ENABLED')==='true'&&
      secret.length>=32&&secret.length<=8192&&!/[\r\n]/.test(secret)&&
      UUID.test(operator)&&typeof requisitar==='function'&&
      typeof enviar==='function'
  }
  const rpc=async (
    acao:keyof typeof RPCS, corpo:Record<string,unknown>
  ):Promise<Record<string,unknown>>=>{
    if(!permitido())throw Error('RPC_HML_DESATIVADA')
    const secret=ambiente.get('SUPABASE_SERVICE_ROLE_KEY')!
    let resposta:Response
    try {
      resposta=await requisitar(BASE+'/rest/v1/rpc/'+RPCS[acao],{
        method:'POST',redirect:'error',
        headers:{
          apikey:secret,authorization:'Bearer '+secret,
          'content-type':'application/json'
        },
        body:JSON.stringify(corpo),
        signal:AbortSignal.timeout(12000)
      })
    }catch{throw Error('RPC_HML_RESPOSTA_INDISPONIVEL')}
    if(!resposta.ok)throw Error('RPC_HML_REJEITADA')
    let data:unknown
    try{data=await resposta.json()}catch{
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    }
    if(!data||typeof data!=='object'||Array.isArray(data))
      throw Error('RPC_HML_RESPOSTA_INVALIDA')
    return data as Record<string,unknown>
  }
  const autorizado=(id:string)=>UUID.test(id)&&
    id===ambiente.get('HML_OPERATOR_UUID')
  return {
    configurado:permitido,
    async listar(limite){
      if(!Number.isInteger(limite)||limite<1||limite>10)
        throw Error('LIMITE_RPC_INVALIDO')
      const op=ambiente.get('HML_OPERATOR_UUID')??''
      if(!autorizado(op))throw Error('OPERADOR_RPC_INVALIDO')
      const r=await rpc('listar',{p_operador:op,p_limite:limite})
      if(r.status!=='ok'||!Array.isArray(r.itens)||
         typeof r.quantidade!=='number'||!Number.isInteger(r.quantidade)||
         r.quantidade!==r.itens.length||
         r.itens.length>limite||
         !r.itens.every(id=>typeof id==='string'&&UUID.test(id)))
        throw Error('FILA_RPC_INCONSISTENTE')
      return {status:'ok',itens:r.itens,quantidade:r.quantidade as number}
    },
    async reservar({outboxId,chave,operadorId}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId))
        throw Error('RESERVA_RPC_INVALIDA')
      const r=await rpc('reservar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId
      })
      if(typeof r.status!=='string'||!ESTADOS_RESERVA.has(r.status))
        throw Error('RESERVA_RPC_INDETERMINADA')
      return {status:r.status as Awaited<ReturnType<OperacoesDespachoHml['reservar']>>['status']}
    },
    async contexto({p_outbox,p_chave,p_operador,p_destinatario_permitido}){
      if(!UUID.test(p_outbox)||!UUID.test(p_chave)||
        !autorizado(p_operador)||!E164.test(p_destinatario_permitido)||
        p_destinatario_permitido!=='+'
          +(ambiente.get('HML_TEST_RECIPIENT_E164')??''))
        throw Error('CONTEXTO_RPC_NAO_AUTORIZADO')
      const resposta=await rpc('contexto',{
        p_outbox,p_chave,p_operador,p_destinatario_permitido
      })
      if(typeof resposta.status!=='string')
        throw Error('CONTEXTO_RPC_INVALIDO')
      return resposta
    },
    async finalizar({outboxId,chave,operadorId,resultado,wamid,codigo}){
      if(!UUID.test(outboxId)||!UUID.test(chave)||!autorizado(operadorId)||
        !ESTADOS_FINAL.has(resultado))
        throw Error('FINALIZACAO_RPC_INVALIDA')
      if(resultado==='aceito_meta'){
        if(typeof wamid!=='string'||!wamidValidoHml(wamid)||codigo!==null)
          throw Error('ACEITE_RPC_INVALIDO')
      }else{
        if(wamid!==null||typeof codigo!=='string'||!CODIGO.test(codigo))
          throw Error('MOTIVO_RPC_INVALIDO')
      }
      const r=await rpc('finalizar',{
        p_outbox:outboxId,p_chave:chave,p_operador:operadorId,
        p_resultado:resultado,p_wamid:wamid,p_codigo:codigo
      })
      if(typeof r.status!=='string'||r.status.length>80)
        throw Error('FINALIZACAO_RPC_RESPOSTA_INVALIDA')
      return {status:r.status}
    },
    async enviar(corpo){
      if(!permitido())throw Error('RPC_HML_DESATIVADA')
      return enviar(corpo)
    }
  }
}

/**
 * KAZA PET • Mensageria • HML
 * Plano de despacho da outbox: composição de RPCs autoritativas e transportador injetado.
 *
 * NÃO IMPORTADO pela Edge publicada. NÃO FAZ rede diretamente.
 * Nunca aceitar parâmetros comerciais, telefone ou texto do navegador.
 * Ativar somente após revisão e homologação E2E de um envio Meta real.
 */
import {wamidValidoHml} from '../mensageria-confirmacao-hml/validarWamidHml.ts'
import {
  montarRespostaDaOutbox,
  type ConsultarContexto,
} from '../mensageria-confirmacao-hml/contextoOutboxBackendHml.ts'
import type {
  EnvioTextoMeta,
} from '../mensageria-confirmacao-hml/respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const DESTINO=/^55[1-9][0-9]{9,10}$/
type EstadoReserva='reservado'|'ja_reservado'|'nao_pronto'|'agenda_invalida'|'janela_inbound_indisponivel'|'outro'
type Finalizacao='aceito_meta'|'recusado_meta'|'indeterminado'

export type ConfigDespachoHml={
  projeto:string
  operadorId:string
  permitidoE164:string // Secret do servidor, sem '+'
  envioHabilitado:boolean
  autorizacaoExpiraIso:string|null
  agora:()=>Date
  chaveAleatoria:()=>string
}
export type OperacoesDespachoHml={
  listar(limite:number):Promise<{status:string;itens:unknown[];quantidade:number}>
  reservar(input:{outboxId:string;chave:string;operadorId:string}):Promise<{status:EstadoReserva}>
  contexto:ConsultarContexto
  enviar(corpo:EnvioTextoMeta):Promise<{httpStatus:number;wamid?:string|null}>
  finalizar(input:{
    outboxId:string;chave:string;operadorId:string;
    resultado:Finalizacao;wamid:string|null;codigo:string|null
  }):Promise<{status:string}>
}
export type ResultadoDespachoHml={
  estado:'bloqueado'|'fila_vazia'|'concorrencia'|'preparo_bloqueado'|
    'indeterminado'|'recusado'|'aceito'|'aceito_sem_registro'
  codigo:string
  aceitosMeta:number
  entregues:number
}

function validacao(cfg:ConfigDespachoHml):boolean{
  const t=cfg.agora().getTime()
  const expira=cfg.autorizacaoExpiraIso?Date.parse(cfg.autorizacaoExpiraIso):NaN
  return cfg.projeto===REF&&cfg.envioHabilitado===true&&UUID.test(cfg.operadorId)&&
    DESTINO.test(cfg.permitidoE164)&&Number.isFinite(t)&&Number.isFinite(expira)&&
    expira>t&&expira-t<=180000
}
export async function executarUmAgradecimentoHml(
  cfg:ConfigDespachoHml,ops:OperacoesDespachoHml
):Promise<ResultadoDespachoHml>{
  const resultado=(estado:ResultadoDespachoHml['estado'],codigo:string):ResultadoDespachoHml=>
    ({estado,codigo,aceitosMeta:0,entregues:0})
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_DE_ENVIO_AUSENTE')
  let itens:unknown[]
  try{
    const fila=await ops.listar(1)
    if(fila.status!=='ok'||!Array.isArray(fila.itens)||
       fila.itens.length>1||fila.quantidade!==fila.itens.length||
       !fila.itens.every(x=>typeof x==='string'&&UUID.test(x)))
      return resultado('bloqueado','FILA_INCONSISTENTE')
    itens=fila.itens
  }catch{return resultado('bloqueado','FILA_INDISPONIVEL')}
  if(itens.length===0)return resultado('fila_vazia','NENHUMA_RESPOSTA_ELEGIVEL')
  if(!validacao(cfg))return resultado('bloqueado','AUTORIZACAO_VENCIDA')

  const outboxId=itens[0] as string
  const chave=cfg.chaveAleatoria()
  if(!UUID.test(chave))return resultado('bloqueado','CHAVE_NAO_VALIDA')
  let reservado:{status:EstadoReserva}
  try{
    reservado=await ops.reservar({outboxId,chave,operadorId:cfg.operadorId})
  }catch{return resultado('bloqueado','RESERVA_NAO_CONFIRMADA')}
  if(reservado.status!=='reservado')
    return resultado('concorrencia','NENHUM_REENVIO_AUTORIZADO')

  const finalizar=async(tipo:Finalizacao,codigo:string|null,wamid:string|null)=>{
    try{
      return (await ops.finalizar({
        outboxId,chave,operadorId:cfg.operadorId,
        resultado:tipo,codigo,wamid
      })).status===tipo
    }catch{return false}
  }

  // A consulta RPC autoritativa verifica convite + webhook assinado +
  // banco/agenda + modelo publicado + clique dentro da janela Meta de 24h.
  const montado=await montarRespostaDaOutbox({
    projeto:cfg.projeto,
    outboxId,chaveTentativa:chave,operadorId:cfg.operadorId,
    destinatarioPermitidoE164:'+'+cfg.permitidoE164
  },ops.contexto)
  if(montado.status!=='pronto'){
    // Sem POST Meta. Mantém tentativa única para análise manual; não reabrir fila.
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','CONTEUDO_OU_CONTEXTO_NAO_ELEGIVEL')
  }
  if(montado.corpo.to!==cfg.permitidoE164||!validacao(cfg)){
    await finalizar('indeterminado','PREPARO_BLOQUEADO',null)
    return resultado('preparo_bloqueado','AUTORIZACAO_EXPIRADA_OU_DESTINO_INCORRETO')
  }
  let meta:{httpStatus:number;wamid?:string|null}
  try{
    meta=await ops.enviar(montado.corpo)
  }catch{
    await finalizar('indeterminado','META_TIMEOUT',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  // HTTP 4xx explícito é recusa. 5xx, 2xx sem wamid e demais são incertos.
  if(Number.isInteger(meta.httpStatus)&&meta.httpStatus>=400&&meta.httpStatus<500){
    await finalizar('recusado_meta','META_HTTP_'+meta.httpStatus,null)
    return resultado('recusado','META_RECUSOU')
  }
  if(meta.httpStatus!==200&&meta.httpStatus!==201||
     !meta.wamid||!wamidValidoHml(meta.wamid)){
    await finalizar('indeterminado','META_ACEITE_INDETERMINADO',null)
    return resultado('indeterminado','RESULTADO_META_INCERTO_SEM_REENVIO')
  }
  const salvo=await finalizar('aceito_meta',null,meta.wamid)
  if(!salvo)return resultado('aceito_sem_registro','ACEITE_META_RECONCILIACAO_MANUAL')
  return {estado:'aceito',codigo:'META_ACEITOU_NAO_E_ENTREGA',aceitosMeta:1,entregues:0}
}

/**
 * Liga RPC autoritativa ao gerador de texto; ainda SEM transporte Meta.
 *
 * Somente backend HML deve executar esta função. Os IDs e a allowlist chegam
 * do backend autenticado/secret manager, nunca do navegador.
 * A RPC SQL é restrita a service_role e exige outbox previamente reservada.
 */
import {prepararAgradecimentoHml,type ContextoRespostaHml,
  type PreparacaoRespostaHml} from './respostaOutboxHml.ts'

const REF='jgtctzqieyorhvqxjbpk'
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
type Config={
  projeto:string
  outboxId:string
  chaveTentativa:string
  operadorId:string
  destinatarioPermitidoE164:string
}
type ResultadoContexto = {status:string} & Record<string,unknown>
export type ConsultarContexto =
  (args:{p_outbox:string;p_chave:string;p_operador:string;p_destinatario_permitido:string})=>Promise<unknown>
export type ResultadoPreparado =
  | {status:'pronto'; corpo:Extract<PreparacaoRespostaHml,{status:'pronto'}>['corpo']}
  | {status:'bloqueado';codigo:string}

const CAMPOS=[
  'eventoCodigo','statusAtendimento','statusConvite','textoModelo',
  'destinatarioE164','remetenteClique','mensagemCliqueId',
  'inicioAtualIso','inicioConviteIso','cliqueRecebidoIso','agoraIso',
  'nomeTutor','nomePet','nomeEmpresa'
] as const

export async function montarRespostaDaOutbox(
  config:Config, consultar:ConsultarContexto
):Promise<ResultadoPreparado> {
  if(config.projeto!==REF ||
     !UUID.test(config.outboxId) ||
     !UUID.test(config.chaveTentativa) ||
     !UUID.test(config.operadorId) ||
     !/^\+55[0-9]{10,11}$/.test(config.destinatarioPermitidoE164))
    return {status:'bloqueado',codigo:'CONTEXTO_HML_NAO_AUTORIZADO'}
  let raw:unknown
  try{
    raw=await consultar({
      p_outbox:config.outboxId,
      p_chave:config.chaveTentativa,
      p_operador:config.operadorId,
      p_destinatario_permitido:config.destinatarioPermitidoE164
    })
  }catch{return {status:'bloqueado',codigo:'CONTEXTO_HML_INDISPONIVEL'}}
  if(!raw||typeof raw!=='object'||Array.isArray(raw))
    return {status:'bloqueado',codigo:'RESPOSTA_RPC_INVALIDA'}
  const r=raw as ResultadoContexto
  if(r.status!=='pronto')return {status:'bloqueado',codigo:'OUTBOX_NAO_ELEGIVEL'}
  if(r.modeloPublicado!==true||CAMPOS.some(k=>typeof r[k]!=='string'))
    return {status:'bloqueado',codigo:'DADOS_RPC_INVALIDOS'}
  if(r.destinatarioE164!==config.destinatarioPermitidoE164)
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  if(r.eventoCodigo!=='AGENDAMENTO_CONFIRMADO_WHATSAPP')
    return {status:'bloqueado',codigo:'EVENTO_NAO_HABILITADO'}
  const result=prepararAgradecimentoHml(r as unknown as ContextoRespostaHml)
  if(result.status!=='pronto')return result
  if(result.corpo.to!==config.destinatarioPermitidoE164.slice(1))
    return {status:'bloqueado',codigo:'DESTINO_DIVERGENTE'}
  return result
}

/**
 * Mensagem de resposta no WhatsApp, montada SOMENTE com contexto obtido
 * e validado no backend. Não faz HTTP, não lê credenciais e não envia mensagens.
 *
 * Origem obrigatória dos dados no serviço futuro:
 * - outbox com estado aguardando_integracao/pronto e convite confirmado;
 * - dados da agenda/grupo/pet/tutor persistidos no banco;
 * - último clique inbound validado HMAC, associado a convite e wamid;
 * - modelo PUBLICADO e versionado, nunca um rascunho local do navegador.
 */
import {wamidValidoHml} from './validarWamidHml.ts'
export type EventoRespostaHml =
  | 'AGENDAMENTO_CONFIRMADO_WHATSAPP'
  | 'REMARCACAO_SOLICITADA_WHATSAPP'
export type ContextoRespostaHml = {
  eventoCodigo:EventoRespostaHml
  statusAtendimento:string
  statusConvite:string
  modeloPublicado:boolean
  textoModelo:string
  destinatarioE164:string
  remetenteClique:string
  mensagemCliqueId:string
  inicioAtualIso:string
  inicioConviteIso:string
  cliqueRecebidoIso:string
  agoraIso:string
  nomeTutor:string
  nomePet:string
  nomeEmpresa:string
}
export type EnvioTextoMeta = {
  messaging_product:'whatsapp'
  recipient_type:'individual'
  to:string
  type:'text'
  context:{message_id:string}
  text:{body:string;preview_url:false}
}
export type PreparacaoRespostaHml =
  | {status:'pronto';corpo:EnvioTextoMeta}
  | {status:'bloqueado';codigo:string}

const MARCADOR=/\{\{\s*([A-Z_0-9]+)\s*\}\}|\{\s*([A-Z_0-9]+)\s*\}/g
const TEXTO_TAG_INCONHECIDA=/{{[^{}]*}}/
const TELEFONE=/^\+55[1-9][0-9]{9,10}$/

function equivalenteWhatsApp(destino:string,origem:string):boolean {
  const normal=destino.slice(1)
  if(origem===normal)return true
  // A Meta pode reportar alguns celulares brasileiros sem o nono dígito.
  return normal.length===13&&normal[4]==='9'&&
    origem===normal.slice(0,4)+normal.slice(5)
}
function horarioLocal(data:Date):{dia:string;hora:string} {
  return {
    dia:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'
    }).format(data),
    hora:new Intl.DateTimeFormat('pt-BR',{
      timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'
    }).format(data),
  }
}
function limparNome(valor:string):string {
  return valor.trim().replace(/[\r\n\t\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').slice(0,80)
}

export function prepararAgradecimentoHml(c:ContextoRespostaHml):PreparacaoRespostaHml {
  if(!c.modeloPublicado||!c.textoModelo?.trim())return {status:'bloqueado',codigo:'MODELO_NAO_PUBLICADO'}
  if(!TELEFONE.test(c.destinatarioE164)||!equivalenteWhatsApp(c.destinatarioE164,c.remetenteClique))
    return {status:'bloqueado',codigo:'DESTINATARIO_NAO_CORRESPONDE'}
  if(!wamidValidoHml(c.mensagemCliqueId))
    return {status:'bloqueado',codigo:'MENSAGEM_ORIGINAL_INVALIDA'}
  const esperado=c.eventoCodigo==='AGENDAMENTO_CONFIRMADO_WHATSAPP'
    ? {atendimento:'confirmado',convite:'confirmado'}
    : {atendimento:'agendado',convite:'remarcacao_pendente'}
  if(c.statusAtendimento!==esperado.atendimento||c.statusConvite!==esperado.convite)
    return {status:'bloqueado',codigo:'ESTADO_DA_AGENDA_DIVERGENTE'}
  const inicio=Date.parse(c.inicioAtualIso),antes=Date.parse(c.inicioConviteIso)
  const clique=Date.parse(c.cliqueRecebidoIso),agora=Date.parse(c.agoraIso)
  if(![inicio,antes,clique,agora].every(Number.isFinite) || inicio!==antes || inicio<=agora)
    return {status:'bloqueado',codigo:'HORARIO_MODIFICADO_OU_INVALIDO'}
  // Margem de 3min para evitar tentar entregar já perto do fim da janela.
  if(clique>agora+60_000 || agora-clique>24*60*60_000-3*60_000)
    return {status:'bloqueado',codigo:'JANELA_24H_NAO_CONFIRMADA'}
  if(![c.nomeTutor,c.nomePet,c.nomeEmpresa].every(s=>typeof s==='string'&&s.trim()))
    return {status:'bloqueado',codigo:'DADOS_INCOMPLETOS'}
  const {dia,hora}=horarioLocal(new Date(inicio))
  const tags:Record<string,string>={
    NOME_TUTOR:limparNome(c.nomeTutor),NOME_PET:limparNome(c.nomePet),
    NOME_EMPRESA:limparNome(c.nomeEmpresa),
    DATA_AGENDAMENTO:dia,HORARIO_AGENDAMENTO:hora,
  }
  let desconhecida=false
  const texto=c.textoModelo.replace(MARCADOR,(_match,keyDuplo:string|undefined,keySimples:string|undefined)=>{
    const key=keyDuplo??keySimples??''
    if(!Object.hasOwn(tags,key)){desconhecida=true;return ''}
    return tags[key]
  }).trim()
  if(desconhecida||TEXTO_TAG_INCONHECIDA.test(texto)||!texto||texto.length>4096)
    return {status:'bloqueado',codigo:'MODELO_TAG_INVALIDA'}
  if(c.eventoCodigo==='REMARCACAO_SOLICITADA_WHATSAPP' &&
    /https?:\/\//i.test(texto))
    return {status:'bloqueado',codigo:'LINK_AUTOATENDIMENTO_INDISPONIVEL'}
  return {status:'pronto',corpo:{
    messaging_product:'whatsapp',recipient_type:'individual',
    to:c.destinatarioE164.slice(1),
    type:'text',context:{message_id:c.mensagemCliqueId},
    text:{body:texto,preview_url:false}
  }}
}
